import { Color } from "../../../src/scripting_api/color.js";
import { describe, it, expect, beforeEach } from "@jest/globals";

describe("Color.convert", () => {
  let color;

  beforeEach(() => {
    color = new Color();
  });

  describe("invalid color space handling", () => {
    it("should return black when target color space is invalid", () => {
      const result = color.convert(["G", 0.5], "INVALID");
      expect(result).toEqual(color.black);
    });

    it("should return black when target color space is null", () => {
      const result = color.convert(["G", 0.5], null);
      expect(result).toEqual(color.black);
    });

    it("should return black when target color space is undefined", () => {
      const result = color.convert(["G", 0.5], undefined);
      expect(result).toEqual(color.black);
    });

    it("should return black when target color space is empty string", () => {
      const result = color.convert(["G", 0.5], "");
      expect(result).toEqual(color.black);
    });

    it("should return black when target color space is a number", () => {
      const result = color.convert(["G", 0.5], 123);
      expect(result).toEqual(color.black);
    });
  });

  describe("transparent color space handling", () => {
    it('should return ["T"] when target color space is "T"', () => {
      const result = color.convert(["RGB", 1, 0, 0], "T");
      expect(result).toEqual(["T"]);
    });

    it('should convert from ["T"] to other color spaces using black', () => {
      // When source is T, it should convert from black
      const result = color.convert(["T"], "G");
      expect(result).toEqual(color.black);
    });
  });

  describe("input validation via _getCorrectColor", () => {
    it("should handle invalid color arrays by defaulting to black", () => {
      const result = color.convert(["INVALID", 1, 2, 3], "G");
      expect(result).toEqual(color.black);
    });

    it("should handle null color array by defaulting to black", () => {
      const result = color.convert(null, "G");
      expect(result).toEqual(color.black);
    });

    it("should handle undefined color array by defaulting to black", () => {
      const result = color.convert(undefined, "G");
      expect(result).toEqual(color.black);
    });

    it("should handle empty array by defaulting to black", () => {
      const result = color.convert([], "G");
      expect(result).toEqual(color.black);
    });

    it("should handle color array with wrong number of components", () => {
      // G should have 2 components [space, value]
      // Invalid input ["G", 0.5, 0.6] defaults to black ["G", 0]
      // Then converts to RGB -> ["RGB", 0, 0, 0]
      const result = color.convert(["G", 0.5, 0.6], "RGB");
      expect(result).toEqual(["RGB", 0, 0, 0]);
    });

    it("should handle color array with out of range values", () => {
      // Values should be between 0 and 1
      // Invalid input ["G", 1.5] defaults to black ["G", 0]
      // Then converts to RGB -> ["RGB", 0, 0, 0]
      const result = color.convert(["G", 1.5], "RGB");
      expect(result).toEqual(["RGB", 0, 0, 0]);
    });
  });

  describe("same color space conversion", () => {
    it("should return the same array when source and target color spaces match", () => {
      const input = ["G", 0.75];
      const result = color.convert(input, "G");
      expect(result).toBe(input); // Should be same reference
    });

    it("should return the same RGB array when converting RGB to RGB", () => {
      const input = ["RGB", 0.2, 0.4, 0.6];
      const result = color.convert(input, "RGB");
      expect(result).toBe(input);
    });

    it("should return the same CMYK array when converting CMYK to CMYK", () => {
      const input = ["CMYK", 0.1, 0.2, 0.3, 0.4];
      const result = color.convert(input, "CMYK");
      expect(result).toBe(input);
    });
  });

  describe("G (grayscale) conversions", () => {
    it("should convert G to RGB", () => {
      const result = color.convert(["G", 0.75], "RGB");
      expect(result[0]).toBe("RGB");
      expect(result[1]).toBeCloseTo(0.75, 10);
      expect(result[2]).toBeCloseTo(0.75, 10);
      expect(result[3]).toBeCloseTo(0.75, 10);
    });

    it("should convert G to CMYK", () => {
      const result = color.convert(["G", 0.25], "CMYK");
      // G_CMYK returns ["CMYK", 0, 0, 0, 1 - g]
      expect(result[0]).toBe("CMYK");
      expect(result[1]).toBe(0);
      expect(result[2]).toBe(0);
      expect(result[3]).toBe(0);
      expect(result[4]).toBeCloseTo(0.75, 10); // 1 - 0.25 = 0.75
    });

    it("should convert RGB to G", () => {
      const result = color.convert(["RGB", 0.3, 0.6, 0.9], "G");
      // 0.3*0.3 + 0.59*0.6 + 0.11*0.9 = 0.09 + 0.354 + 0.099 = 0.543
      expect(result[0]).toBe("G");
      expect(result[1]).toBeCloseTo(0.543, 3);
    });

    it("should convert CMYK to G", () => {
      // CMYK array: [cyan, magenta, yellow, black] = [0.2, 0.3, 0.4, 0.1]
      // CMYK_G destructures as [c, y, m, k] so:
      // c = 0.2 (cyan)
      // y = 0.3 (actually magenta, destructured as y)
      // m = 0.4 (actually yellow, destructured as m)
      // k = 0.1 (black)
      // Formula: 1 - min(1, 0.3*c + 0.59*m + 0.11*y + k)
      // 0.3*0.2 + 0.59*0.4 + 0.11*0.3 + 0.1
      // = 0.06 + 0.236 + 0.033 + 0.1 = 0.429
      // 1 - min(1, 0.429) = 0.571
      const result = color.convert(["CMYK", 0.2, 0.3, 0.4, 0.1], "G");
      expect(result[0]).toBe("G");
      expect(result[1]).toBeCloseTo(0.571, 3);
    });
  });

  describe("RGB to CMYK conversion", () => {
    it("should convert RGB to CMYK", () => {
      const result = color.convert(["RGB", 0.2, 0.4, 0.8], "CMYK");
      // Note: CMYK array is [cyan, magenta, yellow, black]
      // c = 1 - r = 1 - 0.2 = 0.8
      // m = 1 - g = 1 - 0.4 = 0.6  
      // y = 1 - b = 1 - 0.8 = 0.2
      // k = min(c, m, y) = min(0.8, 0.6, 0.2) = 0.2
      // Use toBeCloseTo for floating point comparisons
      expect(result[0]).toBe("CMYK");
      expect(result[1]).toBeCloseTo(0.8, 10);
      expect(result[2]).toBeCloseTo(0.6, 10);
      expect(result[3]).toBeCloseTo(0.2, 10);
      expect(result[4]).toBeCloseTo(0.2, 10);
    });

    it("should convert pure white RGB to CMYK", () => {
      const result = color.convert(["RGB", 1, 1, 1], "CMYK");
      expect(result).toEqual(["CMYK", 0, 0, 0, 0]);
    });

    it("should convert pure black RGB to CMYK", () => {
      const result = color.convert(["RGB", 0, 0, 0], "CMYK");
      expect(result).toEqual(["CMYK", 1, 1, 1, 1]);
    });
  });

  describe("CMYK to RGB conversion", () => {
    it("should convert CMYK to RGB", () => {
      // Note: CMYK array is [cyan, magenta, yellow, black]
      // But CMYK_RGB destructures as [c, y, m, k] (swapped magenta/yellow)
      // So ["CMYK", 0.2, 0.3, 0.4, 0.1] means:
      // c = 0.2 (cyan)
      // y = 0.3 (actually magenta, but destructured as y)
      // m = 0.4 (actually yellow, but destructured as m)
      // k = 0.1 (black)
      const result = color.convert(["CMYK", 0.2, 0.3, 0.4, 0.1], "RGB");
      // r = 1 - min(1, c + k) = 1 - min(1, 0.2 + 0.1) = 1 - 0.3 = 0.7
      // g = 1 - min(1, m + k) = 1 - min(1, 0.4 + 0.1) = 1 - 0.5 = 0.5 (using m which is actually yellow)
      // b = 1 - min(1, y + k) = 1 - min(1, 0.3 + 0.1) = 1 - 0.4 = 0.6 (using y which is actually magenta)
      expect(result[0]).toBe("RGB");
      expect(result[1]).toBeCloseTo(0.7, 10);
      expect(result[2]).toBeCloseTo(0.5, 10);
      expect(result[3]).toBeCloseTo(0.6, 10);
    });

    it("should convert CMYK with k=0 to RGB", () => {
      const result = color.convert(["CMYK", 0.1, 0.2, 0.3, 0], "RGB");
      // c=0.1, y=0.2 (magenta), m=0.3 (yellow), k=0
      // r = 1 - min(1, 0.1+0) = 0.9
      // g = 1 - min(1, 0.3+0) = 0.7 (using m=0.3 which is yellow)
      // b = 1 - min(1, 0.2+0) = 0.8 (using y=0.2 which is magenta)
      expect(result[0]).toBe("RGB");
      expect(result[1]).toBeCloseTo(0.9, 10);
      expect(result[2]).toBeCloseTo(0.7, 10);
      expect(result[3]).toBeCloseTo(0.8, 10);
    });

    it("should convert CMYK with sum > 1 to RGB", () => {
      const result = color.convert(["CMYK", 0.8, 0.7, 0.9, 0.5], "RGB");
      // c=0.8, y=0.7 (magenta), m=0.9 (yellow), k=0.5
      // r = 1 - min(1, 0.8+0.5) = 1 - 1 = 0
      // g = 1 - min(1, 0.9+0.5) = 1 - 1 = 0 (using m=0.9 which is yellow)
      // b = 1 - min(1, 0.7+0.5) = 1 - 1 = 0 (using y=0.7 which is magenta)
      expect(result).toEqual(["RGB", 0, 0, 0]);
    });
  });

  describe("using predefined color constants", () => {
    it("should convert from red constant", () => {
      const result = color.convert(color.red, "G");
      // red = ["RGB", 1, 0, 0] -> G = 0.3*1 + 0.59*0 + 0.11*0 = 0.3
      expect(result[0]).toBe("G");
      expect(result[1]).toBeCloseTo(0.3, 3);
    });

    it("should convert from green constant", () => {
      const result = color.convert(color.green, "G");
      // green = ["RGB", 0, 1, 0] -> G = 0.3*0 + 0.59*1 + 0.11*0 = 0.59
      expect(result[0]).toBe("G");
      expect(result[1]).toBeCloseTo(0.59, 3);
    });

    it("should convert from blue constant", () => {
      const result = color.convert(color.blue, "G");
      // blue = ["RGB", 0, 0, 1] -> G = 0.3*0 + 0.59*0 + 0.11*1 = 0.11
      expect(result[0]).toBe("G");
      expect(result[1]).toBeCloseTo(0.11, 3);
    });

    it("should convert from cyan constant", () => {
      const result = color.convert(color.cyan, "RGB");
      // cyan = ["CMYK", 1, 0, 0, 0]
      // CMYK is [cyan, yellow, magenta, black] based on destructuring in converters
      // c=1, y=0, m=0, k=0
      // r = 1 - min(1, 1+0) = 0
      // g = 1 - min(1, 0+0) = 1
      // b = 1 - min(1, 0+0) = 1
      expect(result).toEqual(["RGB", 0, 1, 1]);
    });

    it("should convert from magenta constant", () => {
      const result = color.convert(color.magenta, "RGB");
      // magenta = ["CMYK", 0, 1, 0, 0]
      // But array is [cyan, yellow, magenta, black], so:
      // c=0, y=1, m=0, k=0
      // r = 1 - min(1, 0+0) = 1
      // g = 1 - min(1, 0+0) = 1
      // b = 1 - min(1, 1+0) = 0
      // Result is yellow [1, 1, 0], not magenta!
      // This suggests the constant might be misnamed or the conversion is wrong
      expect(result).toEqual(["RGB", 1, 1, 0]);
    });

    it("should convert from yellow constant", () => {
      const result = color.convert(color.yellow, "RGB");
      // yellow = ["CMYK", 0, 0, 1, 0]
      // c=0, y=0, m=1, k=0
      // r = 1 - min(1, 0+0) = 1
      // g = 1 - min(1, 1+0) = 0
      // b = 1 - min(1, 0+0) = 1
      // Result is magenta [1, 0, 1], not yellow!
      expect(result).toEqual(["RGB", 1, 0, 1]);
    });
  });

  describe("edge cases and boundary values", () => {
    it("should handle minimum grayscale value", () => {
      const result = color.convert(["G", 0], "RGB");
      expect(result[0]).toBe("RGB");
      expect(result[1]).toBe(0);
      expect(result[2]).toBe(0);
      expect(result[3]).toBe(0);
    });

    it("should handle maximum grayscale value", () => {
      const result = color.convert(["G", 1], "RGB");
      expect(result[0]).toBe("RGB");
      expect(result[1]).toBeCloseTo(1, 10);
      expect(result[2]).toBeCloseTo(1, 10);
      expect(result[3]).toBeCloseTo(1, 10);
    });

    it("should handle minimum RGB values", () => {
      const result = color.convert(["RGB", 0, 0, 0], "G");
      expect(result).toEqual(["G", 0]);
    });

    it("should handle maximum RGB values", () => {
      const result = color.convert(["RGB", 1, 1, 1], "G");
      expect(result[0]).toBe("G");
      expect(result[1]).toBeCloseTo(1, 10);
    });

    it("should handle CMYK values at boundaries", () => {
      const result = color.convert(["CMYK", 0, 0, 0, 0], "G");
      expect(result).toEqual(["G", 1]);
    });

    it("should handle CMYK values at maximum", () => {
      const result = color.convert(["CMYK", 1, 1, 1, 1], "G");
      // 1 - min(1, 0.3*1 + 0.59*1 + 0.11*1 + 1) = 1 - min(1, 2.0) = 1 - 1 = 0
      expect(result).toEqual(["G", 0]);
    });
  });
});

