import { InkDrawingOptions } from "../../../../src/display/editor/ink.js";
import { describe, it, expect, beforeEach, jest } from "@jest/globals";

describe("InkDrawingOptions.updateSVGProperty", () => {
  let viewerParameters;
  let inkDrawingOptions;
  let mockUpdateSVGProperty;

  beforeEach(() => {
    viewerParameters = { realScale: 2.0 };
    inkDrawingOptions = new InkDrawingOptions(viewerParameters);

    // Mock the parent class method
    mockUpdateSVGProperty = jest.fn();
    const parentProto = Object.getPrototypeOf(Object.getPrototypeOf(inkDrawingOptions));
    parentProto.updateSVGProperty = mockUpdateSVGProperty;
  });

  it("should update non-stroke-width property directly", () => {
    inkDrawingOptions.updateSVGProperty("stroke", "red");

    expect(mockUpdateSVGProperty).toHaveBeenCalledWith("stroke", "red");
  });

  it("should scale stroke-width by realScale when value is provided", () => {
    inkDrawingOptions.updateSVGProperty("stroke-width", 5);

    // 5 * 2.0 = 10
    expect(mockUpdateSVGProperty).toHaveBeenCalledWith("stroke-width", 10);
  });

  it("should use current stroke-width when value is undefined", () => {
    // Set current stroke-width
    inkDrawingOptions["stroke-width"] = 3;

    inkDrawingOptions.updateSVGProperty("stroke-width", undefined);

    // 3 * 2.0 = 6
    expect(mockUpdateSVGProperty).toHaveBeenCalledWith("stroke-width", 6);
  });

  it("should use current stroke-width when value is null", () => {
    // Set current stroke-width
    inkDrawingOptions["stroke-width"] = 3;

    inkDrawingOptions.updateSVGProperty("stroke-width", null);

    // 3 * 2.0 = 6
    expect(mockUpdateSVGProperty).toHaveBeenCalledWith("stroke-width", 6);
  });

  it("should handle falsy but not nullish value (0)", () => {
    // 0 is falsy but not nullish, so it should be used as-is
    inkDrawingOptions.updateSVGProperty("stroke-width", 0);

    // 0 * 2.0 = 0
    expect(mockUpdateSVGProperty).toHaveBeenCalledWith("stroke-width", 0);
  });

  it("should handle falsy but not nullish value (false)", () => {
    // false is falsy but not nullish, so it should be used as-is
    inkDrawingOptions.updateSVGProperty("stroke-width", false);

    // false * 2.0 = 0
    expect(mockUpdateSVGProperty).toHaveBeenCalledWith("stroke-width", 0);
  });

  it("should handle falsy but not nullish value (empty string)", () => {
    // "" is falsy but not nullish, so it should be used as-is
    inkDrawingOptions.updateSVGProperty("stroke-width", "");

    // "" * 2.0 = 0
    expect(mockUpdateSVGProperty).toHaveBeenCalledWith("stroke-width", 0);
  });

  it("should use current stroke-width when current value is 0", () => {
    // Set current stroke-width to 0
    inkDrawingOptions["stroke-width"] = 0;

    inkDrawingOptions.updateSVGProperty("stroke-width", undefined);

    // 0 * 2.0 = 0
    expect(mockUpdateSVGProperty).toHaveBeenCalledWith("stroke-width", 0);
  });

  it("should handle zero realScale", () => {
    viewerParameters.realScale = 0;
    inkDrawingOptions = new InkDrawingOptions(viewerParameters);
    const parentProto = Object.getPrototypeOf(Object.getPrototypeOf(inkDrawingOptions));
    parentProto.updateSVGProperty = mockUpdateSVGProperty;

    inkDrawingOptions.updateSVGProperty("stroke-width", 5);

    // 5 * 0 = 0
    expect(mockUpdateSVGProperty).toHaveBeenCalledWith("stroke-width", 0);
  });

  it("should handle fractional realScale", () => {
    viewerParameters.realScale = 0.5;
    inkDrawingOptions = new InkDrawingOptions(viewerParameters);
    const parentProto = Object.getPrototypeOf(Object.getPrototypeOf(inkDrawingOptions));
    parentProto.updateSVGProperty = mockUpdateSVGProperty;

    inkDrawingOptions.updateSVGProperty("stroke-width", 5);

    // 5 * 0.5 = 2.5
    expect(mockUpdateSVGProperty).toHaveBeenCalledWith("stroke-width", 2.5);
  });

  it("should handle negative stroke-width", () => {
    inkDrawingOptions.updateSVGProperty("stroke-width", -3);

    // -3 * 2.0 = -6
    expect(mockUpdateSVGProperty).toHaveBeenCalledWith("stroke-width", -6);
  });

  it("should handle negative realScale", () => {
    viewerParameters.realScale = -1;
    inkDrawingOptions = new InkDrawingOptions(viewerParameters);
    const parentProto = Object.getPrototypeOf(Object.getPrototypeOf(inkDrawingOptions));
    parentProto.updateSVGProperty = mockUpdateSVGProperty;

    inkDrawingOptions.updateSVGProperty("stroke-width", 5);

    // 5 * -1 = -5
    expect(mockUpdateSVGProperty).toHaveBeenCalledWith("stroke-width", -5);
  });

  it("should handle multiple property updates", () => {
    inkDrawingOptions.updateSVGProperty("stroke", "blue");
    inkDrawingOptions.updateSVGProperty("stroke-width", 2);
    inkDrawingOptions.updateSVGProperty("stroke-opacity", 0.5);

    expect(mockUpdateSVGProperty).toHaveBeenCalledTimes(3);
    expect(mockUpdateSVGProperty).toHaveBeenCalledWith("stroke", "blue");
    expect(mockUpdateSVGProperty).toHaveBeenCalledWith("stroke-width", 4); // 2 * 2.0
    expect(mockUpdateSVGProperty).toHaveBeenCalledWith("stroke-opacity", 0.5);
  });

  it("should handle stroke-width with decimal precision", () => {
    viewerParameters.realScale = 1.5;
    inkDrawingOptions = new InkDrawingOptions(viewerParameters);
    const parentProto = Object.getPrototypeOf(Object.getPrototypeOf(inkDrawingOptions));
    parentProto.updateSVGProperty = mockUpdateSVGProperty;

    inkDrawingOptions.updateSVGProperty("stroke-width", 1.25);

    // 1.25 * 1.5 = 1.875
    expect(mockUpdateSVGProperty).toHaveBeenCalledWith("stroke-width", 1.875);
  });

  it("should pass through non-stroke-width properties unchanged", () => {
    inkDrawingOptions.updateSVGProperty("stroke-opacity", 0.7);
    inkDrawingOptions.updateSVGProperty("stroke-linecap", "square");
    inkDrawingOptions.updateSVGProperty("fill", "red");

    expect(mockUpdateSVGProperty).toHaveBeenCalledWith("stroke-opacity", 0.7);
    expect(mockUpdateSVGProperty).toHaveBeenCalledWith("stroke-linecap", "square");
    expect(mockUpdateSVGProperty).toHaveBeenCalledWith("fill", "red");
  });

  it("should handle case sensitivity of property names", () => {
    // Property names should be case-sensitive
    inkDrawingOptions.updateSVGProperty("STROKE-WIDTH", 5); // Different case
    inkDrawingOptions.updateSVGProperty("Stroke-Width", 3); // Different case

    // These should NOT be scaled since they don't match "stroke-width" exactly
    expect(mockUpdateSVGProperty).toHaveBeenCalledWith("STROKE-WIDTH", 5);
    expect(mockUpdateSVGProperty).toHaveBeenCalledWith("Stroke-Width", 3);
  });
});

