import { InkEditor } from "../../../../src/display/editor/ink.js";
import { AnnotationEditor } from "../../../../src/display/editor/editor.js";
import { describe, it, expect, beforeEach, jest } from "@jest/globals";

describe("InkEditor.serialize", () => {
  let inkEditor;
  let mockSerializeDraw;
  let mockParent;
  let mockUiManager;
  let mockColorManagerConvert;
  let mockAddComment;

  beforeEach(() => {
    // Mock parent and uiManager
    mockParent = {
      getNextId: jest.fn(() => "test-id"),
      drawLayer: {},
      dimensions: [100, 100],
      viewport: {
        rotation: 0,
        rawDims: {
          pageWidth: 100,
          pageHeight: 100,
          pageX: 0,
          pageY: 0,
        },
      },
    };

    mockUiManager = {
      viewParameters: { realScale: 1 },
    };

    // Mock ColorManager.convert
    mockColorManagerConvert = jest.fn((color) => [255, 0, 0]); // Return red color array

    // Setup static properties
    AnnotationEditor._colorManager = {
      convert: mockColorManagerConvert,
    };

    // Create InkEditor instance
    inkEditor = new InkEditor({
      parent: mockParent,
      id: "test-editor-id",
      uiManager: mockUiManager,
    });

    // Mock serializeDraw method
    mockSerializeDraw = jest.fn(() => ({
      lines: [[0, 0, 10, 10]],
      points: [[5, 5]],
    }));
    inkEditor.serializeDraw = mockSerializeDraw;

    // Mock addComment method
    mockAddComment = jest.fn();
    inkEditor.addComment = mockAddComment;

    // Mock parent.serialize method
    const mockSuperSerialize = jest.fn(() => ({
      annotationType: "ink",
      pageIndex: 0,
      rect: [0, 0, 100, 100],
      rotation: 0,
      structTreeParentId: null,
      popupRef: "",
    }));

    // Get the parent prototype (DrawingEditor -> AnnotationEditor)
    const parentProto = Object.getPrototypeOf(Object.getPrototypeOf(inkEditor));
    parentProto.serialize = mockSuperSerialize;

    // Mock serializeDeleted method
    inkEditor.serializeDeleted = jest.fn(() => ({
      id: "test-annotation-id",
      deleted: true,
      pageIndex: 0,
      popupRef: "",
    }));

    // Mock isEmpty method
    inkEditor.isEmpty = jest.fn(() => false);

    // Set default drawing options
    inkEditor._drawingOptions = {
      stroke: "#ff0000",
      "stroke-opacity": 0.8,
      "stroke-width": 2,
    };

    // Initialize other properties
    inkEditor.deleted = false;
    inkEditor.annotationElementId = null;
    inkEditor._initialData = null;
    inkEditor.pageIndex = 0;
  });

  it("should return null when editor is empty", () => {
    inkEditor.isEmpty.mockReturnValue(true);

    const result = inkEditor.serialize();

    expect(result).toBeNull();
    expect(inkEditor.isEmpty).toHaveBeenCalled();
    expect(mockSerializeDraw).not.toHaveBeenCalled();
  });

  it("should call serializeDeleted when editor is deleted", () => {
    inkEditor.deleted = true;

    const result = inkEditor.serialize();

    expect(result).toEqual({
      id: "test-annotation-id",
      deleted: true,
      pageIndex: 0,
      popupRef: "",
    });
