describe("InkEditor.renderAnnotationElement", () => {
  let inkEditor;
  let mockAnnotation;
  let mockSerializeDraw;
  let mockParent;
  let mockUiManager;

  beforeEach(() => {
    // Mock parent and uiManager
    mockParent = {
      getNextId: jest.fn(() => "test-id"),
      drawLayer: {},
      dimensions: [100, 100],
      viewport: {
        rotation: 0,
        rawDims: {
          pageWidth: 100,
          pageHeight: 100,
          pageX: 0,
          pageY: 0,
        },
      },
    };

    mockUiManager = {
      viewParameters: { realScale: 1 },
      hasCommentManager: jest.fn(() => false),
      updateComment: jest.fn(),
      removeComment: jest.fn(),
      getNonHCMColor: jest.fn(() => "#000000"),
    };

    // Create InkEditor instance
    inkEditor = new InkEditor({
      parent: mockParent,
      id: "test-editor-id",
      uiManager: mockUiManager,
    });

    // Mock serializeDraw method
    mockSerializeDraw = jest.fn(() => ({
      points: [[0, 0], [10, 10], [20, 5]],
      rect: [5, 5, 25, 15],
    }));
    inkEditor.serializeDraw = mockSerializeDraw;

    // Mock annotation with hide and updateEdited methods
    mockAnnotation = {
      hide: jest.fn(),
      updateEdited: jest.fn(),
    };

    // Set default drawing options
    inkEditor._drawingOptions = {
      "stroke-width": 2,
    };

    // Initialize other properties
    inkEditor.deleted = false;
    inkEditor.comment = "Test comment";
  });

  it("should call annotation.hide() and return null when editor is deleted", () => {
    inkEditor.deleted = true;

    const result = inkEditor.renderAnnotationElement(mockAnnotation);

    expect(result).toBeNull();
    expect(mockAnnotation.hide).toHaveBeenCalled();
    expect(mockSerializeDraw).not.toHaveBeenCalled();
    expect(mockAnnotation.updateEdited).not.toHaveBeenCalled();
  });

  it("should call serializeDraw with isForCopying = false", () => {
    inkEditor.renderAnnotationElement(mockAnnotation);

    expect(mockSerializeDraw).toHaveBeenCalledWith(false);
  });

  it("should call annotation.updateEdited with correct parameters", () => {
    const expectedPoints = [[0, 0], [10, 10], [20, 5]];
    const expectedRect = [5, 5, 25, 15];

    inkEditor.renderAnnotationElement(mockAnnotation);

    expect(mockAnnotation.updateEdited).toHaveBeenCalledWith({
      rect: expectedRect,
      thickness: 2,
      points: expectedPoints,
      popup: expect.objectContaining({
        text: "Test comment",
        deleted: false,
        opacity: 1,
      }),
    });
  });

  it("should return null after updating annotation", () => {
    const result = inkEditor.renderAnnotationElement(mockAnnotation);

    expect(result).toBeNull();
  });

  it("should use correct stroke-width from drawing options", () => {
    inkEditor._drawingOptions["stroke-width"] = 3.5;

    inkEditor.renderAnnotationElement(mockAnnotation);

    expect(mockAnnotation.updateEdited).toHaveBeenCalledWith(
      expect.objectContaining({
        thickness: 3.5,
      })
    );
  });

  it("should handle comment being null", () => {
    // When comment is set to null, it becomes empty string and deleted: true
    inkEditor.comment = null;

    inkEditor.renderAnnotationElement(mockAnnotation);

    expect(mockAnnotation.updateEdited).toHaveBeenCalledWith(
      expect.objectContaining({
        popup: expect.objectContaining({
          text: "",
          deleted: true,
        }),
      })
    );
  });

  it("should handle comment being undefined", () => {
    // When comment is set to undefined, it calls uiManager.removeComment
    inkEditor.comment = undefined;

    inkEditor.renderAnnotationElement(mockAnnotation);

    expect(mockAnnotation.updateEdited).toHaveBeenCalledWith(
      expect.objectContaining({
        popup: expect.objectContaining({
          text: undefined,
          deleted: false,
        }),
      })
    );
  });

  it("should handle empty points array from serializeDraw", () => {
    mockSerializeDraw.mockReturnValue({
      points: [],
      rect: [0, 0, 0, 0],
    });

    inkEditor.renderAnnotationElement(mockAnnotation);

    expect(mockAnnotation.updateEdited).toHaveBeenCalledWith(
      expect.objectContaining({
        points: [],
        rect: [0, 0, 0, 0],
      })
    );
  });

  it("should handle null rect from serializeDraw", () => {
    mockSerializeDraw.mockReturnValue({
      points: [[0, 0], [10, 10]],
      rect: null,
    });

    inkEditor.renderAnnotationElement(mockAnnotation);

    expect(mockAnnotation.updateEdited).toHaveBeenCalledWith(
      expect.objectContaining({
        points: [[0, 0], [10, 10]],
        rect: null,
      })
    );
  });

  it("should handle missing stroke-width property in drawing options", () => {
    inkEditor._drawingOptions = {
      // No stroke-width property
      stroke: "#ff0000",
      "stroke-opacity": 1,
    };

    inkEditor.renderAnnotationElement(mockAnnotation);

    // thickness should be undefined when stroke-width is missing
    expect(mockAnnotation.updateEdited).toHaveBeenCalledWith({
      rect: [5, 5, 25, 15],
      thickness: undefined,
      points: [[0, 0], [10, 10], [20, 5]],
      popup: expect.objectContaining({
        text: "Test comment",
      }),
    });
  });

  it("should handle missing drawing options - expect error", () => {
    // This test documents that the code throws when _drawingOptions is missing
    // We need to handle this case in the test by catching the error
    delete inkEditor._drawingOptions;

    // The actual code will throw TypeError when accessing this._drawingOptions["stroke-width"]
    // We'll verify this behavior
    expect(() => inkEditor.renderAnnotationElement(mockAnnotation)).toThrow(TypeError);
  });
});

