      // Create button with swatch
      const button = colorPicker.renderButton();
      // Get the swatch that was created
      const swatch = button.querySelector(".swatch");

      // Don't create dropdown - updateColor should handle null dropdown

      const testColor = "#FF9900";
      colorPicker.updateColor(testColor);

      // Check button swatch style was updated
      expect(swatch.style.backgroundColor).toBe(testColor);
    });

    it("should not throw error when buttonSwatch is null", () => {
      const colorPicker = new ColorPicker({ uiManager: mockUiManager });

      // Don't render button, so buttonSwatch will be null
      // The dropdown should also be null since we haven't rendered it

      const testColor = "#FF9900";

      // Should not throw - updateColor should handle null buttonSwatch
      expect(() => colorPicker.updateColor(testColor)).not.toThrow();
    });

    it("should handle case when dropdown is not rendered", () => {
      const colorPicker = new ColorPicker({ uiManager: mockUiManager });

      // Create button with swatch
      const button = colorPicker.renderButton();
      const swatch = button.querySelector(".swatch");

      // Don't create dropdown, so it remains null

      const testColor = "#FF9900";
      colorPicker.updateColor(testColor);

      // Should update button swatch
      expect(swatch.style.backgroundColor).toBe(testColor);
      // No error should be thrown even though dropdown is null
    });

    it("should set correct ariaSelected on dropdown children when color matches", () => {
      const colorPicker = new ColorPicker({ uiManager: mockUiManager });

      // Create button
      const button = colorPicker.renderButton();

