    tabIndex: '',
    attributes: {},
    style: {},
    children: [],
    append: jest.fn(function(child) {
      this.children.push(child);
      // Don't try to set parentElement as it's read-only in real DOM
      if (this.children.length === 1) {
        this.firstChild = child;
        this.firstElementChild = child;
      }
      this.lastElementChild = child;
    }),
    addEventListener: jest.fn(),
    querySelector: jest.fn(function(selector) {
      if (selector === '.swatch') {
        return this.children.find(child => child.className === 'swatch') || null;
      }
      return null;
    }),
    setAttribute: jest.fn(function(name, value) {
      this.attributes[name] = value;
    }),
    getAttribute: jest.fn(function(name) {
      return this.attributes[name];
    }),
    ariaHasPopup: '',
    ariaControls: '',
    ariaExpanded: '',
    ariaSelected: false,
    ariaHidden: '',
    firstChild: null,
    firstElementChild: null,
    lastElementChild: null,
    nextSibling: null,
    previousSibling: null,
    focus: jest.fn(),
    remove: jest.fn(),
    classList: {
      add: jest.fn(),
      remove: jest.fn(),
      contains: jest.fn(),
    },
    contains: jest.fn(),
  };

  return element;
};

global.document.createElement = jest.fn(createMockElement);

describe("ColorPicker.destroy", () => {
  let mockUiManager;
  let mockEventBus;
  let mockAbortSignal;

  beforeEach(() => {
    mockAbortSignal = new AbortController().signal;

    mockEventBus = {
      dispatch: jest.fn(),
    };

    mockUiManager = {
      _eventBus: mockEventBus,
      _signal: mockAbortSignal,
      highlightColors: new Map([
        ["yellow", "#FFFF00"],
        ["red", "#FF0000"],
        ["green", "#00FF00"],
      ]),
      combinedSignal: jest.fn(function(ac) {
        return ac.signal;
      }),
    };

    // Reset all mocks
    jest.clearAllMocks();
    // Clear any stored elements from previous tests
    document.createElement.mockClear();
  });

  describe("basic functionality", () => {
    it("should call remove on button and dropdown when they exist", () => {
      const colorPicker = new ColorPicker({ uiManager: mockUiManager });

      // Create button and dropdown
      const button = colorPicker.renderButton();
      const dropdown = colorPicker.renderMainDropdown();

      // Verify mocks are set up
      expect(button.remove).toBeDefined();
      expect(dropdown.remove).toBeDefined();

      // Clear mock calls before destroy
      button.remove.mockClear();
      dropdown.remove.mockClear();

      // Call destroy
      colorPicker.destroy();

      // Should call remove on button
      expect(button.remove).toHaveBeenCalledTimes(1);

      // Should call remove on dropdown
      expect(dropdown.remove).toHaveBeenCalledTimes(1);
    });

    it("should set button, buttonSwatch, and dropdown to null", () => {
      const colorPicker = new ColorPicker({ uiManager: mockUiManager });

      // Create button and dropdown
      colorPicker.renderButton();
      colorPicker.renderMainDropdown();

      // Call destroy
      colorPicker.destroy();

      // After destroy, internal properties should be null
      // We can't directly access private fields, but we can verify
      // the destroy method doesn't throw and completes execution
      expect(() => colorPicker.destroy()).not.toThrow();

      // Calling destroy multiple times should not throw
      expect(() => colorPicker.destroy()).not.toThrow();
    });

    it("should handle case when only button exists (no dropdown)", () => {
      const colorPicker = new ColorPicker({ uiManager: mockUiManager });

      // Create only button, not dropdown
      const button = colorPicker.renderButton();

      // Clear mock calls before destroy
      button.remove.mockClear();

      // Call destroy
      colorPicker.destroy();

      // Should call remove on button
      expect(button.remove).toHaveBeenCalledTimes(1);

      // Should not throw even though dropdown is null
      expect(() => colorPicker.destroy()).not.toThrow();
    });

    it("should handle case when only dropdown exists (no button)", () => {
      const colorPicker = new ColorPicker({ uiManager: mockUiManager });

      // Create only dropdown, not button
      const dropdown = colorPicker.renderMainDropdown();

      // Clear mock calls before destroy
      dropdown.remove.mockClear();

      // Call destroy
      colorPicker.destroy();

      // Should call remove on dropdown
      expect(dropdown.remove).toHaveBeenCalledTimes(1);

      // Should not throw even though button is null
      expect(() => colorPicker.destroy()).not.toThrow();
    });

    it("should handle case when neither button nor dropdown exists", () => {
      const colorPicker = new ColorPicker({ uiManager: mockUiManager });

      // Don't create button or dropdown

      // Call destroy - should not throw
      expect(() => colorPicker.destroy()).not.toThrow();

      // Can call destroy multiple times without issues
      expect(() => colorPicker.destroy()).not.toThrow();
      expect(() => colorPicker.destroy()).not.toThrow();
    });
  });

  describe("with editor", () => {
    it("should destroy color picker associated with editor", () => {
      const mockEditor = {
        id: "test-editor-1",
        color: "#00FF00",
        _uiManager: mockUiManager,
      };

      const colorPicker = new ColorPicker({ editor: mockEditor });

      // Create button and dropdown
      const button = colorPicker.renderButton();
      const dropdown = colorPicker.renderMainDropdown();

      // Clear mock calls before destroy
      button.remove.mockClear();
      dropdown.remove.mockClear();

      // Call destroy
      colorPicker.destroy();

      // Should call remove on button
      expect(button.remove).toHaveBeenCalledTimes(1);

      // Should call remove on dropdown
      expect(dropdown.remove).toHaveBeenCalledTimes(1);

      // Should not throw on subsequent calls
      expect(() => colorPicker.destroy()).not.toThrow();
    });

    it("should handle editor without color property", () => {
      const mockEditor = {
        id: "test-editor-no-color",
        _uiManager: mockUiManager,
        // No color property
      };

      const colorPicker = new ColorPicker({ editor: mockEditor });

      // Create button and dropdown
      const button = colorPicker.renderButton();
      const dropdown = colorPicker.renderMainDropdown();

      // Clear mock calls before destroy
      button.remove.mockClear();
      dropdown.remove.mockClear();

      // Call destroy
      colorPicker.destroy();

      // Should call remove on button
      expect(button.remove).toHaveBeenCalledTimes(1);

      // Should call remove on dropdown
      expect(dropdown.remove).toHaveBeenCalledTimes(1);
    });
  });

  describe("edge cases", () => {
    it("should handle destroy after destroy (idempotent)", () => {
      const colorPicker = new ColorPicker({ uiManager: mockUiManager });

      // Create button and dropdown
      const button = colorPicker.renderButton();
      const dropdown = colorPicker.renderMainDropdown();

      // Clear mock calls
      button.remove.mockClear();
      dropdown.remove.mockClear();

      // First destroy
      colorPicker.destroy();

      // Verify remove was called
      expect(button.remove).toHaveBeenCalledTimes(1);
      expect(dropdown.remove).toHaveBeenCalledTimes(1);

      // Second destroy should not throw
      expect(() => colorPicker.destroy()).not.toThrow();

      // Remove should not be called again since elements are null
      expect(button.remove).toHaveBeenCalledTimes(1);
      expect(dropdown.remove).toHaveBeenCalledTimes(1);
    });

    it("should handle destroy when remove method throws", () => {
      const colorPicker = new ColorPicker({ uiManager: mockUiManager });

      // Create button and dropdown
      const button = colorPicker.renderButton();
      const dropdown = colorPicker.renderMainDropdown();

      // Make remove method throw an error
      button.remove.mockImplementation(() => {
        throw new Error("Mock remove error");
      });

      dropdown.remove.mockImplementation(() => {
        throw new Error("Mock remove error");
      });

      // Destroy should propagate the error since optional chaining (?.) 
      // only checks if left side is null/undefined, not if method throws
      expect(() => colorPicker.destroy()).toThrow("Mock remove error");

      // Remove should have been called (at least one of them)
      // Note: The first remove that throws will stop execution
      // So we can't guarantee both were called
      expect(button.remove).toHaveBeenCalledTimes(1);
    });

    it("should handle null values for button and dropdown", () => {
      const colorPicker = new ColorPicker({ uiManager: mockUiManager });

      // Don't create button or dropdown, so they remain null

      // Destroy should handle null values gracefully
      expect(() => colorPicker.destroy()).not.toThrow();

      // Verify no remove calls were made
      // Since we didn't create elements, document.createElement wasn't called
      // But we can still verify the method doesn't throw
    });

    it("should work with empty highlightColors map", () => {
      const mockUiManagerEmptyColors = {
        _eventBus: mockEventBus,
        _signal: mockAbortSignal,
        highlightColors: new Map(),
        combinedSignal: jest.fn(function(ac) {
          return ac.signal;
        }),
      };

      const colorPicker = new ColorPicker({ uiManager: mockUiManagerEmptyColors });

      // Create button and dropdown (dropdown will have no color options)
      const button = colorPicker.renderButton();
      const dropdown = colorPicker.renderMainDropdown();

      // Clear mock calls before destroy
      button.remove.mockClear();
      dropdown.remove.mockClear();

      // Call destroy
      colorPicker.destroy();

      // Should call remove on button
      expect(button.remove).toHaveBeenCalledTimes(1);

      // Should call remove on dropdown
      expect(dropdown.remove).toHaveBeenCalledTimes(1);
    });
  });

  describe("integration with other methods", () => {
    it("should allow render after destroy", () => {
      const colorPicker = new ColorPicker({ uiManager: mockUiManager });

      // Create and destroy
      const button1 = colorPicker.renderButton();
      const dropdown1 = colorPicker.renderMainDropdown();
      colorPicker.destroy();

      // Clear mock to track new element creation
      document.createElement.mockClear();

      // Render again after destroy
      const button2 = colorPicker.renderButton();
      const dropdown2 = colorPicker.renderMainDropdown();

      // Should create new elements
      expect(document.createElement).toHaveBeenCalledWith("button");
      expect(document.createElement).toHaveBeenCalledWith("span");
      expect(document.createElement).toHaveBeenCalledWith("div");

      // New elements should have remove method
      expect(button2.remove).toBeDefined();
      expect(dropdown2.remove).toBeDefined();

      // Destroy again
      colorPicker.destroy();

      // Should call remove on new elements
      expect(button2.remove).toHaveBeenCalledTimes(1);
      expect(dropdown2.remove).toHaveBeenCalledTimes(1);
    });

    it("should not interfere with updateColor after destroy", () => {
      const colorPicker = new ColorPicker({ uiManager: mockUiManager });

      // Create, then destroy
      colorPicker.renderButton();
      colorPicker.renderMainDropdown();
      colorPicker.destroy();

      // updateColor should not throw after destroy
      // It should handle null buttonSwatch and dropdown gracefully
      expect(() => colorPicker.updateColor("#FF0000")).not.toThrow();

      // Can call destroy again
      expect(() => colorPicker.destroy()).not.toThrow();
    });

    it("should work with hideDropdown after destroy", () => {
      const colorPicker = new ColorPicker({ uiManager: mockUiManager });

      // Create, then destroy
      colorPicker.renderButton();
      colorPicker.renderMainDropdown();
      colorPicker.destroy();

      // hideDropdown should throw after destroy because #button is null
      // and line 260 doesn't use optional chaining for #button.ariaExpanded
      expect(() => colorPicker.hideDropdown()).toThrow(TypeError);
    });
  });
});

