describe("Comment.finish", () => {
  let mockEditor;
  let mockUiManager;
  let mockAbortSignal;

  beforeEach(() => {
    mockAbortSignal = new AbortController().signal;

    mockUiManager = {
      _signal: mockAbortSignal,
      hasCommentManager: jest.fn(() => true),
      getCommentDialogElement: jest.fn(() => ({})),
      direction: "ltr",
      editComment: jest.fn(),
    };

    mockEditor = {
      _uiManager: mockUiManager,
      commentButtonColor: "#ff0000",
      commentButtonPosition: [0.5, 0.5],
      parent: {
        boundingClientRect: {
          width: 800,
          height: 600,
          x: 0,
          y: 0,
        },
      },
      _focusEventsAllowed: true,
    };

    // Reset all mocks
    jest.clearAllMocks();
    document.createElement.mockClear();
  });

  describe("basic functionality", () => {
    it("should call focus on commentToolbarButton when it exists", () => {
      const comment = new Comment(mockEditor);

      // Render toolbar button to create #commentToolbarButton
      const button = comment.renderForToolbar();
      expect(button).toBeDefined();

      // Call finish
      comment.finish();

      // Check focus was called on the button
      expect(button.focus).toHaveBeenCalledWith({
        focusVisible: false,
      });
    });

    it("should do nothing when commentToolbarButton is null", () => {
      const comment = new Comment(mockEditor);

      // Don't render toolbar button, so #commentToolbarButton will be null
      // finish should check if #commentToolbarButton exists and return early

      // Should not throw
      expect(() => comment.finish()).not.toThrow();

      // document.createElement should not have been called for button
      expect(document.createElement).not.toHaveBeenCalledWith("button");
    });

    it("should set focusVisible to true when commentWasFromKeyBoard is true", () => {
      const comment = new Comment(mockEditor);

      // Render toolbar button
      const button = comment.renderForToolbar();
      expect(button).toBeDefined();

      // Set commentWasFromKeyBoard to true
      // We can't directly access the private field, so we need to trigger it
      // by simulating a keyboard event. Let's check if there's a way to set it.
      // Looking at the code, commentWasFromKeyBoard is set to true in keydown event handler
      // when Enter key is pressed on the button.

      // First, let's get the keydown event listener
      const keydownListener = button.addEventListener.mock.calls.find(
        call => call[0] === 'keydown'
      )?.[1];

      expect(keydownListener).toBeDefined();

      // Simulate keydown event with Enter key
      const mockEvent = {
        target: button,
        key: 'Enter',
        preventDefault: jest.fn(),
      };
      keydownListener(mockEvent);

      // Now call finish
      comment.finish();

      // Check focus was called with focusVisible: true
      expect(button.focus).toHaveBeenCalledWith({
        focusVisible: true,
      });
    });

    it("should set commentWasFromKeyBoard to false after calling finish", () => {
      const comment = new Comment(mockEditor);

      // Render toolbar button
      const button = comment.renderForToolbar();

      // Trigger keydown to set commentWasFromKeyBoard to true
      const keydownListener = button.addEventListener.mock.calls.find(
        call => call[0] === 'keydown'
      )?.[1];

      const mockEvent = {
        target: button,
        key: 'Enter',
        preventDefault: jest.fn(),
      };
      keydownListener(mockEvent);

      // Call finish first time
      comment.finish();

      // focus should have been called with focusVisible: true
      expect(button.focus).toHaveBeenCalledWith({
        focusVisible: true,
      });

      // Reset the focus mock
      button.focus.mockClear();

      // Call finish second time
      comment.finish();

      // Now focus should be called with focusVisible: false
      // because commentWasFromKeyBoard was reset to false after first call
      expect(button.focus).toHaveBeenCalledWith({
        focusVisible: false,
      });
    });
  });

  describe("integration with render methods", () => {
    it("should work after renderForToolbar is called", () => {
      const comment = new Comment(mockEditor);

      // Initially, commentToolbarButton should be null
      // finish should do nothing
      comment.finish();

      // Render toolbar button
      const button = comment.renderForToolbar();

      // Now finish should work
      comment.finish();
      expect(button.focus).toHaveBeenCalled();
    });

    it("should not work with standalone button, only toolbar button", () => {
      const comment = new Comment(mockEditor);

      // Render standalone button (not toolbar)
      const standaloneButton = comment.renderForStandalone();
      expect(standaloneButton).toBeDefined();

      // finish should do nothing since #commentToolbarButton is null
      comment.finish();
      expect(standaloneButton.focus).not.toHaveBeenCalled();

      // Now render toolbar button
      const toolbarButton = comment.renderForToolbar();

      // finish should now work
      comment.finish();
      expect(toolbarButton.focus).toHaveBeenCalled();
    });

    it("should work after removeToolbarCommentButton and re-render", () => {
      const comment = new Comment(mockEditor);

      // Render toolbar button
      const button1 = comment.renderForToolbar();
      comment.finish();
      expect(button1.focus).toHaveBeenCalled();

      // Remove toolbar button
      comment.removeToolbarCommentButton();

      // Reset mock
      button1.focus.mockClear();

      // finish should do nothing now
      comment.finish();
      expect(button1.focus).not.toHaveBeenCalled();

      // Re-render toolbar button
      const button2 = comment.renderForToolbar();

      // finish should work again
      comment.finish();
      expect(button2.focus).toHaveBeenCalled();
    });
  });

  describe("edge cases", () => {
    it("should handle when button focus method is missing", () => {
      const comment = new Comment(mockEditor);

      // Create a custom mock button without focus method
      const buttonWithoutFocus = createMockButtonElement();
      delete buttonWithoutFocus.focus;

      // Mock document.createElement to return our custom button
      document.createElement.mockReturnValueOnce(buttonWithoutFocus);

      // Render toolbar button
      comment.renderForToolbar();

