      comment.finish();
      expect(button.focus).toHaveBeenCalled();

      // Reset mock
      button.focus.mockClear();

      // Destroy comment
      comment.destroy();

      // finish should do nothing after destroy
      comment.finish();
      expect(button.focus).not.toHaveBeenCalled();
    });

    it("should handle multiple calls to finish", () => {
      const comment = new Comment(mockEditor);

      // Render toolbar button
      const button = comment.renderForToolbar();

      // Call finish multiple times
      comment.finish();
      comment.finish();
      comment.finish();

      // focus should be called each time
      expect(button.focus).toHaveBeenCalledTimes(3);

      // Each call should have focusVisible: false
      expect(button.focus).toHaveBeenNthCalledWith(1, { focusVisible: false });
      expect(button.focus).toHaveBeenNthCalledWith(2, { focusVisible: false });
      expect(button.focus).toHaveBeenNthCalledWith(3, { focusVisible: false });
    });

