      const button = comment.renderForToolbar();

      // Get the keydown event listener
      const keydownListener = button.addEventListener.mock.calls.find(
        call => call[0] === 'keydown'
      )?.[1];

      // Simulate keyboard interaction to set commentWasFromKeyBoard to true
      const mockEvent = {
        target: button,
        key: 'Enter',
        preventDefault: jest.fn(),
      };
      keydownListener(mockEvent);

      // Remove the toolbar button
      comment.removeToolbarCommentButton();

      // finish should do nothing since button no longer exists
      expect(() => comment.finish()).not.toThrow();

      // focus should not be called
      expect(button.focus).not.toHaveBeenCalled();
    });

    it("should handle focus with different keyboard keys (not Enter)", () => {
      const comment = new Comment(mockEditor);

      // Render toolbar button
      const button = comment.renderForToolbar();

      // Get the keydown event listener
      const keydownListener = button.addEventListener.mock.calls.find(
        call => call[0] === 'keydown'
      )?.[1];

