describe("Comment.removeStandaloneCommentButton", () => {
  let mockEditor;
  let mockUiManager;
  let mockAbortSignal;

  beforeEach(() => {
    mockAbortSignal = new AbortController().signal;

    mockUiManager = {
      _signal: mockAbortSignal,
      updatePopupColor: jest.fn(),
      hasCommentManager: jest.fn(() => true),
      getCommentDialogElement: jest.fn(() => ({})),
      direction: "ltr",
    };

    mockEditor = {
      _uiManager: mockUiManager,
      commentButtonColor: "#ff0000",
      commentButtonPosition: [0.5, 0.5],
      parent: {
        boundingClientRect: {
          width: 800,
          height: 600,
          x: 0,
          y: 0,
        },
      },
      _focusEventsAllowed: true,
    };

    // Reset all mocks
    jest.clearAllMocks();
    document.createElement.mockClear();
  });

  describe("basic functionality", () => {
    it("should call remove on commentStandaloneButton when it exists", () => {
      const comment = new Comment(mockEditor);

      // Render standalone button to create #commentStandaloneButton
      const button = comment.renderForStandalone();
      expect(button).toBeDefined();

      // Call removeStandaloneCommentButton
      comment.removeStandaloneCommentButton();

      // Check remove was called on the button
      expect(button.remove).toHaveBeenCalledTimes(1);
    });

    it("should set commentStandaloneButton to null after removal", () => {
      const comment = new Comment(mockEditor);

      // Render standalone button
      const button = comment.renderForStandalone();
      expect(button).toBeDefined();

      // Call removeStandaloneCommentButton
      comment.removeStandaloneCommentButton();

      // Try to get comment button width or other methods that check #commentStandaloneButton
      // They should handle null gracefully
      expect(() => comment.commentButtonWidth).not.toThrow();
      expect(comment.commentButtonWidth).toBe(0);
    });

    it("should do nothing when commentStandaloneButton is null", () => {
      const comment = new Comment(mockEditor);

      // Don't render standalone button, so #commentStandaloneButton will be null
      // removeStandaloneCommentButton should check if #commentStandaloneButton exists and use optional chaining

      // Should not throw
      expect(() => comment.removeStandaloneCommentButton()).not.toThrow();

      // document.createElement should not have been called for button
      expect(document.createElement).not.toHaveBeenCalledWith("button");
    });

    it("should handle when button remove method is missing", () => {
      const comment = new Comment(mockEditor);

      // Create a custom mock button without remove method
      const buttonWithoutRemove = createMockButtonElement();
      delete buttonWithoutRemove.remove;

      // Mock document.createElement to return our custom button
      document.createElement.mockReturnValueOnce(buttonWithoutRemove);

      // Render standalone button
      comment.renderForStandalone();

      // This will throw because optional chaining (?.) returns undefined,
      // but the code tries to call remove() as a function
      expect(() => comment.removeStandaloneCommentButton()).toThrow(TypeError);
      expect(() => comment.removeStandaloneCommentButton()).toThrow("not a function");
    });
  });

  describe("integration with other methods", () => {
    it("should prevent other methods from using standalone button after removal", () => {
      const comment = new Comment(mockEditor);

      // Render standalone button
      const button = comment.renderForStandalone();

      // Check commentButtonWidth works before removal
      const widthBefore = comment.commentButtonWidth;
      expect(widthBefore).toBeGreaterThan(0);

      // Remove button
      comment.removeStandaloneCommentButton();

      // Check commentButtonWidth after removal
      const widthAfter = comment.commentButtonWidth;
      expect(widthAfter).toBe(0);

      // Check other methods that depend on #commentStandaloneButton
      expect(comment.commentPopupPositionInLayer).toBeNull();
    });

    it("should work with onUpdatedColor after removal", () => {
      const comment = new Comment(mockEditor);

      // Render standalone button
      comment.renderForStandalone();

      // Remove button
      comment.removeStandaloneCommentButton();

      // onUpdatedColor should do nothing when #commentStandaloneButton is null
      expect(() => comment.onUpdatedColor()).not.toThrow();
      expect(mockUiManager.updatePopupColor).not.toHaveBeenCalled();
    });

    it("should work with setCommentButtonStates after removal", () => {
      const comment = new Comment(mockEditor);

      // Render standalone button
      const button = comment.renderForStandalone();

      // Remove button
      comment.removeStandaloneCommentButton();

      // setCommentButtonStates should return early when #commentStandaloneButton is null
      expect(() => comment.setCommentButtonStates({ selected: true, hasPopup: true })).not.toThrow();
      // Button classList.toggle should not have been called
      expect(button.classList.toggle).not.toHaveBeenCalled();
    });

    it("should allow re-rendering after removal", () => {
      const comment = new Comment(mockEditor);

      // Render standalone button first time
      const button1 = comment.renderForStandalone();
      expect(button1).toBeDefined();

      // Remove button
      comment.removeStandaloneCommentButton();

      // Render standalone button again
      const button2 = comment.renderForStandalone();
      expect(button2).toBeDefined();
      expect(button2).not.toBe(button1);

      // New button should work
      expect(comment.commentButtonWidth).toBeGreaterThan(0);
    });
  });

  describe("multiple calls", () => {
    it("should handle multiple calls to removeStandaloneCommentButton", () => {
      const comment = new Comment(mockEditor);

      // Render standalone button
      const button = comment.renderForStandalone();

      // Call remove multiple times
      comment.removeStandaloneCommentButton();
      comment.removeStandaloneCommentButton();
      comment.removeStandaloneCommentButton();

      // remove should only be called once
      expect(button.remove).toHaveBeenCalledTimes(1);
    });

    it("should handle calling remove on already null button", () => {
      const comment = new Comment(mockEditor);

      // Call remove when button is null
      comment.removeStandaloneCommentButton();

      // Render button
      const button = comment.renderForStandalone();

      // Remove button
      comment.removeStandaloneCommentButton();

      // Call remove again
      comment.removeStandaloneCommentButton();

      // remove should only be called once
      expect(button.remove).toHaveBeenCalledTimes(1);
    });
  });

  describe("interaction with removeToolbarCommentButton", () => {
    it("should only remove standalone button, not toolbar button", () => {
      const comment = new Comment(mockEditor);

      // Render both buttons
      const toolbarButton = comment.renderForToolbar();
      const standaloneButton = comment.renderForStandalone();

      // Remove standalone button
      comment.removeStandaloneCommentButton();

      // Only standalone button should have remove called
      expect(standaloneButton.remove).toHaveBeenCalledTimes(1);
      expect(toolbarButton.remove).not.toHaveBeenCalled();

      // Toolbar button should still be accessible
      expect(() => comment.finish()).not.toThrow();
    });

    it("should allow standalone button removal while toolbar button exists", () => {
      const comment = new Comment(mockEditor);

      // Render both buttons
      const toolbarButton = comment.renderForToolbar();
      const standaloneButton = comment.renderForStandalone();

      // Remove standalone button
      comment.removeStandaloneCommentButton();

      // Toolbar button methods should still work
      comment.finish();
      expect(toolbarButton.focus).toHaveBeenCalled();

      // Standalone button methods should not work
      expect(comment.commentButtonWidth).toBe(0);
    });
  });

  describe("edge cases", () => {
    it("should work after destroy method is called", () => {
      const comment = new Comment(mockEditor);

      // Render standalone button
      const button = comment.renderForStandalone();

      // Call removeStandaloneCommentButton first
      comment.removeStandaloneCommentButton();
      expect(button.remove).toHaveBeenCalledTimes(1);

      // Reset mock
      button.remove.mockClear();

      // Destroy comment
      comment.destroy();

      // removeStandaloneCommentButton should do nothing after destroy
      comment.removeStandaloneCommentButton();
      expect(button.remove).not.toHaveBeenCalled();
    });

    it("should work when called from destroy method", () => {
      const comment = new Comment(mockEditor);

      // Render standalone button
      const button = comment.renderForStandalone();

      // Destroy should call remove on the button
      comment.destroy();
      expect(button.remove).toHaveBeenCalledTimes(1);
    });

    it("should handle when button is already removed from DOM", () => {
      const comment = new Comment(mockEditor);

      // Render standalone button
      const button = comment.renderForStandalone();

      // Simulate button already removed from DOM (remove method still exists)
      button.remove.mockImplementation(() => {
        // This simulates remove being called on an already removed element
      });

      // Should not throw
      expect(() => comment.removeStandaloneCommentButton()).not.toThrow();
      expect(button.remove).toHaveBeenCalledTimes(1);
    });

    it("should handle when button remove method throws an error", () => {
      const comment = new Comment(mockEditor);

      // Create a custom mock button with remove method that throws
      const buttonWithThrowingRemove = createMockButtonElement();
      buttonWithThrowingRemove.remove = jest.fn(() => {
        throw new Error("Remove error");
      });

      // Mock document.createElement to return our custom button
      document.createElement.mockReturnValueOnce(buttonWithThrowingRemove);

      // Render standalone button
      comment.renderForStandalone();

      // Should throw when remove method throws
      expect(() => comment.removeStandaloneCommentButton()).toThrow("Remove error");
    });

    it("should handle null button after removal in all scenarios", () => {
      const comment = new Comment(mockEditor);

      // Render standalone button
      const button = comment.renderForStandalone();

      // Remove button
      comment.removeStandaloneCommentButton();

      // Test all methods that use #commentStandaloneButton
      expect(comment.commentButtonWidth).toBe(0);
      expect(comment.commentPopupPositionInLayer).toBeNull();
      expect(() => comment.onUpdatedColor()).not.toThrow();
      expect(() => comment.setCommentButtonStates({ selected: true, hasPopup: true })).not.toThrow();

      // Button should not be used
      expect(button.remove).toHaveBeenCalledTimes(1);
    });

    it("should work with optional chaining for missing properties", () => {
      const comment = new Comment(mockEditor);

      // Render standalone button with minimal mock that has all required methods
      const minimalButton = {
        tagName: "BUTTON",
        className: "",
        style: {
          backgroundColor: "",
          insetInlineEnd: "",
          top: "",
        },
        attributes: {},
        addEventListener: jest.fn(),
        setAttribute: jest.fn(),
        getAttribute: jest.fn(() => null),
        remove: jest.fn(),
        classList: {
          add: jest.fn(),
          remove: jest.fn(),
          contains: jest.fn(),
          toggle: jest.fn(),
        },
        ariaExpanded: "false",
      };

      document.createElement.mockReturnValueOnce(minimalButton);
      comment.renderForStandalone();

      // Should work with optional chaining even if button is missing some properties
      expect(() => comment.removeStandaloneCommentButton()).not.toThrow();
      expect(minimalButton.remove).toHaveBeenCalledTimes(1);
    });
  });
});

