describe("Comment.serialize", () => {
  let mockEditor;
  let mockUiManager;
  let mockAbortSignal;

  beforeEach(() => {
    mockAbortSignal = new AbortController().signal;

    mockUiManager = {
      _signal: mockAbortSignal,
      hasCommentManager: jest.fn(() => true),
      getCommentDialogElement: jest.fn(() => ({})),
      direction: "ltr",
      editComment: jest.fn(),
    };

    mockEditor = {
      _uiManager: mockUiManager,
      commentButtonColor: "#ff0000",
      commentButtonPosition: [0.5, 0.5],
      parent: {
        boundingClientRect: {
          width: 800,
          height: 600,
          x: 0,
          y: 0,
        },
      },
      _focusEventsAllowed: true,
    };

    // Reset all mocks
    jest.clearAllMocks();
    document.createElement.mockClear();
  });

  describe("basic functionality", () => {
    it("should return data property", () => {
      const comment = new Comment(mockEditor);

      // Initially, data should be default values
      const result = comment.serialize();
      expect(result).toBeDefined();
      expect(result).toEqual(comment.data);
    });

    it("should return object with text, richText, date, and deleted properties", () => {
      const comment = new Comment(mockEditor);

      const result = comment.serialize();

      expect(result).toHaveProperty("text");
      expect(result).toHaveProperty("richText");
      expect(result).toHaveProperty("date");
      expect(result).toHaveProperty("deleted");
    });

    it("should return default values for new comment", () => {
      const comment = new Comment(mockEditor);

      const result = comment.serialize();

      // By default, text should be null, richText null, date null, deleted false
      expect(result.text).toBeNull();
      expect(result.richText).toBeNull();
      expect(result.date).toBeNull();
      expect(result.deleted).toBe(false);
    });
  });

  describe("with text data", () => {
    it("should return serialized data with text", () => {
      const comment = new Comment(mockEditor);
      const testText = "Test comment text";

      // Set data using setter
      comment.data = testText;

      const result = comment.serialize();

      expect(result.text).toBe(testText);
      expect(result.richText).toBeNull(); // Should be null when text changes
      expect(result.date).toBeInstanceOf(Date);
      expect(result.deleted).toBe(false);
    });

    it("should return serialized data with richText preserved", () => {
      const comment = new Comment(mockEditor);
      const initialText = "Initial text";
      const richText = "<p>Rich text content</p>";

      // Use setInitialText to preserve richText
      comment.setInitialText(initialText, richText);

      const result = comment.serialize();

      expect(result.text).toBe(initialText);
      expect(result.richText).toBe(richText);
      expect(result.date).toBeNull(); // date should be null when set via setInitialText
      expect(result.deleted).toBe(false);
    });

    it("should return updated date when text changes", () => {
      const comment = new Comment(mockEditor);

      // Set initial data
      comment.data = "First text";
      const firstResult = comment.serialize();
      const firstDate = firstResult.date;

      expect(firstDate).toBeInstanceOf(Date);

      // Set new data - date should be updated
      comment.data = "Second text";
      const secondResult = comment.serialize();
      const secondDate = secondResult.date;

      expect(secondDate).toBeInstanceOf(Date);
      // Dates should be different instances (new Date() creates new instance)
      expect(secondDate).not.toBe(firstDate);
    });

    it("should handle empty string text", () => {
      const comment = new Comment(mockEditor);

      comment.data = "";

      const result = comment.serialize();

      expect(result.text).toBe("");
      expect(result.date).toBeInstanceOf(Date);
      expect(result.deleted).toBe(true); // isDeleted() returns true when text === ""
    });
  });

  describe("deleted state", () => {
    it("should return deleted true when text is empty string", () => {
      const comment = new Comment(mockEditor);

      // isDeleted() returns true when text is empty string
      comment.data = "";

      const result = comment.serialize();
      expect(result.deleted).toBe(true); // isDeleted() returns true when text === ""
    });

    it("should return deleted true when set to null", () => {
      const comment = new Comment(mockEditor);

      // Setting data to null marks as deleted
      comment.data = null;

      const result = comment.serialize();
      expect(result.text).toBe("");
      expect(result.deleted).toBe(true);
    });

    it("should return deleted true after destroy", () => {
      const comment = new Comment(mockEditor);

      comment.data = "Some text";
      comment.destroy();

      const result = comment.serialize();
      expect(result.text).toBe("");
      expect(result.deleted).toBe(true);
    });
  });

  describe("consistency with data property", () => {
    it("should always return same as data getter", () => {
      const comment = new Comment(mockEditor);

      // Test multiple times with different data
      comment.data = "First";
      expect(comment.serialize()).toEqual(comment.data);

      comment.data = "Second";
      expect(comment.serialize()).toEqual(comment.data);

      comment.data = null;
      expect(comment.serialize()).toEqual(comment.data);
    });

    it("should reflect changes to data property", () => {
      const comment = new Comment(mockEditor);

      const initialData = comment.serialize();
      expect(initialData.text).toBeNull();

      comment.data = "Updated text";
      const updatedData = comment.serialize();
      expect(updatedData.text).toBe("Updated text");
    });
  });

  describe("edge cases", () => {
    it("should work with null text", () => {
      const comment = new Comment(mockEditor);

      // Don't set data, text should remain null
      const result = comment.serialize();
      expect(result.text).toBeNull();
    });

    it("should handle very long text", () => {
      const comment = new Comment(mockEditor);
      const longText = "A".repeat(10000);

      comment.data = longText;

      const result = comment.serialize();
      expect(result.text).toBe(longText);
      expect(result.text.length).toBe(10000);
    });

    it("should handle special characters in text", () => {
      const comment = new Comment(mockEditor);
      const specialText = "Line1\nLine2\tTab\\Backslash\"Quote'Single";

      comment.data = specialText;

      const result = comment.serialize();
      expect(result.text).toBe(specialText);
    });

    it("should work after multiple serializations", () => {
      const comment = new Comment(mockEditor);
      comment.data = "Test";

      // Call serialize multiple times
      const result1 = comment.serialize();
      const result2 = comment.serialize();
      const result3 = comment.serialize();

      // All should be equal
      expect(result1).toEqual(result2);
      expect(result2).toEqual(result3);
      expect(result1).toEqual(result3);
    });

    it("should work with rich text containing HTML", () => {
      const comment = new Comment(mockEditor);
      const text = "Comment";
      const richText = "<div><strong>Bold</strong> <em>Italic</em></div>";

      comment.setInitialText(text, richText);

      const result = comment.serialize();
      expect(result.text).toBe(text);
      expect(result.richText).toBe(richText);
    });

    it("should maintain richText when text doesn't change", () => {
      const comment = new Comment(mockEditor);
      const text = "Same text";
      const richText = "<p>Rich</p>";

      comment.setInitialText(text, richText);

      // Set same text again through data setter
      comment.data = text;

      const result = comment.serialize();
      // richText should be preserved because text hasn't changed
      expect(result.richText).toBe(richText);
    });
  });
});

