import { InkDrawOutliner } from "../../../../../src/display/editor/drawers/inkdraw.js";
import { describe, it, expect, beforeEach } from "@jest/globals";

describe("InkDrawOutliner.updateProperty", () => {
  let outliner;

  beforeEach(() => {
    // Create an InkDrawOutliner instance with some initial values
    outliner = new InkDrawOutliner(50, 60, 1000, 800, 0, 2);
  });

  it("should update thickness when name is 'stroke-width'", () => {
    // Initial thickness should be 2 (from constructor)
    // We can't directly access #thickness since it's private
    // but we can test by checking that the property update works

    // Call updateProperty with stroke-width
    outliner.updateProperty("stroke-width", 5);

    // Since #thickness is private, we need to verify through other means
    // The thickness is used in getOutlines method, but that's complex to test
    // However, we can verify the function doesn't throw and returns nothing
    // (updateProperty returns undefined)

    const result = outliner.updateProperty("stroke-width", 5);
    expect(result).toBeUndefined();

    // We could also test that subsequent behavior reflects the change
    // but that would require calling other methods
  });

  it("should handle different numeric values for stroke-width", () => {
    // Test with zero
    outliner.updateProperty("stroke-width", 0);
    const result1 = outliner.updateProperty("stroke-width", 0);
    expect(result1).toBeUndefined();

    // Test with negative value (though this might not be valid in practice)
    outliner.updateProperty("stroke-width", -1);
    const result2 = outliner.updateProperty("stroke-width", -1);
    expect(result2).toBeUndefined();

    // Test with decimal value
    outliner.updateProperty("stroke-width", 2.5);
    const result3 = outliner.updateProperty("stroke-width", 2.5);
    expect(result3).toBeUndefined();

    // Test with large value
    outliner.updateProperty("stroke-width", 100);
    const result4 = outliner.updateProperty("stroke-width", 100);
    expect(result4).toBeUndefined();
  });

  it("should handle string values for stroke-width", () => {
    // The function might accept string values that can be converted to numbers
    outliner.updateProperty("stroke-width", "3");
    const result1 = outliner.updateProperty("stroke-width", "3");
    expect(result1).toBeUndefined();

    outliner.updateProperty("stroke-width", "0.5");
    const result2 = outliner.updateProperty("stroke-width", "0.5");
    expect(result2).toBeUndefined();
  });

  it("should do nothing for other property names", () => {
    // Test with other property names that should be ignored
    const result1 = outliner.updateProperty("stroke", "red");
    expect(result1).toBeUndefined();

    const result2 = outliner.updateProperty("fill", "blue");
    expect(result2).toBeUndefined();

    const result3 = outliner.updateProperty("opacity", 0.5);
    expect(result3).toBeUndefined();

    const result4 = outliner.updateProperty("stroke-dasharray", "5,5");
    expect(result4).toBeUndefined();

    const result5 = outliner.updateProperty("unknown-property", "some-value");
    expect(result5).toBeUndefined();
  });

  it("should handle case sensitivity for property names", () => {
    // Property name should be case-sensitive
    // "stroke-width" with different casing should be ignored
    const result1 = outliner.updateProperty("Stroke-Width", 5);
    expect(result1).toBeUndefined();

    const result2 = outliner.updateProperty("STROKE-WIDTH", 5);
    expect(result2).toBeUndefined();

    const result3 = outliner.updateProperty("stroke-Width", 5);
    expect(result3).toBeUndefined();
  });

  it("should work correctly with null or undefined values", () => {
    // The function should handle null/undefined values for stroke-width
    outliner.updateProperty("stroke-width", null);
    const result1 = outliner.updateProperty("stroke-width", null);
    expect(result1).toBeUndefined();

    outliner.updateProperty("stroke-width", undefined);
    const result2 = outliner.updateProperty("stroke-width", undefined);
    expect(result2).toBeUndefined();
  });

  it("should work when called multiple times with different values", () => {
    // Test sequence of updates
    outliner.updateProperty("stroke-width", 2);
    const result1 = outliner.updateProperty("stroke-width", 2);
    expect(result1).toBeUndefined();

    outliner.updateProperty("stroke-width", 4);
    const result2 = outliner.updateProperty("stroke-width", 4);
    expect(result2).toBeUndefined();

    outliner.updateProperty("stroke-width", 1);
    const result3 = outliner.updateProperty("stroke-width", 1);
    expect(result3).toBeUndefined();
  });

  it("should not affect other properties when updating stroke-width", () => {
    // Ensure that updating stroke-width doesn't break other functionality
    // by calling other methods before and after update
    outliner.updateProperty("stroke-width", 3);

    // The drawing should not be empty initially since constructor adds one line
    expect(outliner.isEmpty()).toBe(false);

    // The drawing should be cancellable initially (fewer than 10 points)
    // Initially there's only 1 point (x, y), which is 2 elements in the points array
    expect(outliner.isCancellable()).toBe(true);
  });
});

