import { InkDrawOutline } from "../../../../../src/display/editor/drawers/inkdraw.js";
import { describe, it, expect, beforeEach } from "@jest/globals";

describe("InkDrawOutline.build", () => {
  let outline;
  let mockLines;

  beforeEach(() => {
    // Create mock lines data
    // Simple line with one point for basic tests
    mockLines = [
      {
        line: new Float64Array([NaN, NaN, NaN, NaN, 0.3, 0.4])
      }
    ];
    outline = new InkDrawOutline();
  });

  it("should set all properties correctly with valid parameters", () => {
    // Build with all parameters
    outline.build(mockLines, 1000, 800, 1.5, 90, 3.0, 5);

    // Verify all properties are set correctly
    expect(outline.thickness).toBe(3.0);
    // Check that box is computed (should not be null/undefined)
    expect(outline.box).toBeDefined();
    expect(Array.isArray(outline.box) || outline.box instanceof Float32Array).toBe(true);
  });

  it("should handle default innerMargin when not provided", () => {
    // Build without innerMargin (should default to 0)
    outline.build(mockLines, 1000, 800, 1.0, 0, 2.0);

    // Verify thickness is set
    expect(outline.thickness).toBe(2.0);
    // Box should be computed
    expect(outline.box).toBeDefined();
  });

  it("should handle null innerMargin", () => {
    // Build with explicit null innerMargin
    outline.build(mockLines, 1000, 800, 1.0, 0, 2.0, null);

    // Should default to 0 when null
    expect(outline.thickness).toBe(2.0);
    expect(outline.box).toBeDefined();
  });

  it("should compute bbox for simple point lines", () => {
    // Simple line with one point
    const simpleLines = [
      {
        line: new Float64Array([NaN, NaN, NaN, NaN, 0.2, 0.3])
      }
    ];

    outline.build(simpleLines, 1000, 800, 1.0, 0, 1.0, 0);

    const bbox = outline.box;
    expect(bbox).toBeDefined();
    expect(bbox.length).toBe(4);

    // With thickness=1 and innerMargin=0, bbox should be around the point
    // Since there's margin calculation, values should be clamped between 0 and 1
    expect(bbox[0]).toBeGreaterThanOrEqual(0);
    expect(bbox[1]).toBeGreaterThanOrEqual(0);
    expect(bbox[2]).toBeGreaterThanOrEqual(0); // width
    expect(bbox[3]).toBeGreaterThanOrEqual(0); // height
  });

  it("should compute bbox for bezier curve lines", () => {
    // Line with bezier curve (more than 12 elements)
    const bezierLines = [
      {
        line: new Float64Array([
          NaN, NaN, NaN, NaN, // First 4 are NaN (starting point)
          0.1, 0.1, // Starting point (x, y)
          0.2, 0.2, 0.3, 0.3, 0.4, 0.4, // First bezier control points and end point
          0.5, 0.5, 0.6, 0.6, 0.7, 0.7  // Second bezier segment
        ])
      }
    ];

    outline.build(bezierLines, 1000, 800, 1.0, 0, 2.0, 1);

    const bbox = outline.box;
    expect(bbox).toBeDefined();
    expect(bbox.length).toBe(4);

    // Bbox should be valid
    expect(bbox[0]).toBeGreaterThanOrEqual(0);
    expect(bbox[1]).toBeGreaterThanOrEqual(0);
    expect(bbox[2]).toBeGreaterThanOrEqual(0);
    expect(bbox[3]).toBeGreaterThanOrEqual(0);
  });

  it("should handle different rotation values", () => {
    // Test all valid rotations: 0, 90, 180, 270
    const rotations = [0, 90, 180, 270];

    for (const rotation of rotations) {
      outline.build(mockLines, 1000, 800, 1.0, rotation, 2.0, 0);
      expect(outline.box).toBeDefined();

      const bbox = outline.box;
      expect(bbox[0]).toBeGreaterThanOrEqual(0);
      expect(bbox[1]).toBeGreaterThanOrEqual(0);
      expect(bbox[2]).toBeGreaterThanOrEqual(0);
      expect(bbox[3]).toBeGreaterThanOrEqual(0);
    }
  });

  it("should handle different parent scales", () => {
    const scales = [0.5, 1.0, 1.5, 2.0];

    for (const scale of scales) {
      outline.build(mockLines, 1000, 800, scale, 0, 2.0, 0);
      expect(outline.box).toBeDefined();

      const bbox = outline.box;
      expect(bbox[0]).toBeGreaterThanOrEqual(0);
      expect(bbox[1]).toBeGreaterThanOrEqual(0);
      expect(bbox[2]).toBeGreaterThanOrEqual(0);
      expect(bbox[3]).toBeGreaterThanOrEqual(0);
    }
  });

  it("should handle different thickness values", () => {
    const thicknesses = [0, 0.5, 1.0, 5.0, 10.0, 100.0];

    for (const thickness of thicknesses) {
      outline.build(mockLines, 1000, 800, 1.0, 0, thickness, 0);
      expect(outline.thickness).toBe(thickness);
      expect(outline.box).toBeDefined();
    }
  });

  it("should handle different innerMargin values", () => {
    const margins = [0, 1, 5, 10, 50];

    for (const margin of margins) {
      outline.build(mockLines, 1000, 800, 1.0, 0, 2.0, margin);
      expect(outline.box).toBeDefined();
    }
  });

  it("should handle empty lines array", () => {
    // Empty lines should still work
    const emptyLines = [];

    outline.build(emptyLines, 1000, 800, 1.0, 0, 2.0, 0);

    expect(outline.box).toBeDefined();
    const bbox = outline.box;

    // With no lines, bbox starts as [Infinity, Infinity, -Infinity, -Infinity]
    // After margin calculation and clamping, it becomes [1, 1, 0, 0]
    // Then width = 0 - 1 = -1, height = 0 - 1 = -1
    // But actually looking at the code: bbox[2] and bbox[3] are width and height
    // So we just check they're defined
    expect(bbox.length).toBe(4);
    // Values should be finite numbers
    expect(Number.isFinite(bbox[0])).toBe(true);
    expect(Number.isFinite(bbox[1])).toBe(true);
    expect(Number.isFinite(bbox[2])).toBe(true);
    expect(Number.isFinite(bbox[3])).toBe(true);
  });

  it("should handle multiple lines", () => {
    const multipleLines = [
      {
        line: new Float64Array([NaN, NaN, NaN, NaN, 0.1, 0.1])
      },
      {
        line: new Float64Array([NaN, NaN, NaN, NaN, 0.5, 0.5])
      },
      {
        line: new Float64Array([NaN, NaN, NaN, NaN, 0.9, 0.9])
      }
    ];

    outline.build(multipleLines, 1000, 800, 1.0, 0, 2.0, 1);

    expect(outline.box).toBeDefined();
    const bbox = outline.box;

    // Bbox should encompass all points
    expect(bbox[0]).toBeGreaterThanOrEqual(0);
    expect(bbox[1]).toBeGreaterThanOrEqual(0);
    expect(bbox[0] + bbox[2]).toBeLessThanOrEqual(1); // x + width ≤ 1
    expect(bbox[1] + bbox[3]).toBeLessThanOrEqual(1); // y + height ≤ 1
  });

  it("should handle lines with closure (Z command)", () => {
    // Line with length 6 (indicates closure with Z)
    const closedLine = [
      {
        line: new Float64Array([NaN, NaN, NaN, NaN, 0.3, 0.4]) // length = 6
      }
    ];

    outline.build(closedLine, 1000, 800, 1.0, 0, 2.0, 0);

    expect(outline.box).toBeDefined();
    const bbox = outline.box;
    expect(bbox.length).toBe(4);
  });

  it("should handle lines with straight segment (L command)", () => {
    // Line with length 12 and NaN at position 6 (indicates straight segment)
    const straightLineData = new Float64Array(12);
    straightLineData[4] = 0.2; // x1
    straightLineData[5] = 0.3; // y1
    straightLineData[6] = NaN; // indicates straight segment
    straightLineData[10] = 0.6; // x2
    straightLineData[11] = 0.7; // y2

    const straightLine = [
      {
        line: straightLineData
      }
    ];

    outline.build(straightLine, 1000, 800, 1.0, 0, 2.0, 0);

    expect(outline.box).toBeDefined();
    const bbox = outline.box;
    expect(bbox.length).toBe(4);
  });

  it("should update properties correctly after build", () => {
    // First build
    outline.build(mockLines, 1000, 800, 1.0, 0, 2.0, 1);
    const bbox1 = outline.box.slice(); // Create a copy

    // Update thickness
    const updatedBbox = outline.updateProperty("stroke-width", 5.0);
    expect(outline.thickness).toBe(5.0);
    expect(updatedBbox).toBe(outline.box);

    // Bbox might change or might not change much depending on margin calculation
    const bbox2 = outline.box;
    // At minimum, the box reference should be the same (it's updated in place)
    expect(updatedBbox).toBe(bbox2);
    // But the actual values might be different
    // Let's just verify thickness was updated
    expect(outline.thickness).toBe(5.0);
  });

  it("should recompute bbox correctly when rebuild with different parameters", () => {
    // First build
    outline.build(mockLines, 1000, 800, 1.0, 0, 2.0, 1);
    const bbox1 = outline.box.slice(); // Copy

    // Rebuild with different parameters
    outline.build(mockLines, 800, 600, 1.5, 90, 3.0, 2);
    const bbox2 = outline.box;

    // Should be different
    expect(bbox2).not.toEqual(bbox1);
    expect(outline.thickness).toBe(3.0);
  });

  it("should handle edge case with thickness=0 and innerMargin=0", () => {
    outline.build(mockLines, 1000, 800, 1.0, 0, 0, 0);

    expect(outline.thickness).toBe(0);
    expect(outline.box).toBeDefined();

    const bbox = outline.box;
    // With zero thickness and margin, bbox should be exactly the point
    expect(bbox[0]).toBeGreaterThanOrEqual(0);
    expect(bbox[1]).toBeGreaterThanOrEqual(0);
  });

  it("should handle large thickness values", () => {
    outline.build(mockLines, 1000, 800, 1.0, 0, 100.0, 10);

    expect(outline.thickness).toBe(100.0);
    expect(outline.box).toBeDefined();

    const bbox = outline.box;
    // With large thickness, bbox might be clamped to [0, 0, 1, 1]
    expect(bbox[0]).toBeGreaterThanOrEqual(0);
    expect(bbox[1]).toBeGreaterThanOrEqual(0);
    expect(bbox[0] + bbox[2]).toBeLessThanOrEqual(1);
    expect(bbox[1] + bbox[3]).toBeLessThanOrEqual(1);
  });

  it("should handle floating point precision in coordinates", () => {
    // Lines with floating point coordinates
    const fpLines = [
      {
        line: new Float64Array([NaN, NaN, NaN, NaN, 0.123456789, 0.987654321])
      }
    ];

    outline.build(fpLines, 1000, 800, 1.0, 0, 2.0, 0);

    expect(outline.box).toBeDefined();
    const bbox = outline.box;
    expect(bbox.length).toBe(4);
  });
});

