import { validateRangeRequestCapabilities } from "../../../src/display/network_utils.js";
import { describe, it, expect, jest, beforeEach, afterEach } from "@jest/globals";

describe("validateRangeRequestCapabilities", () => {
  // Helper function to create mock headers
  function createMockHeaders(headers = {}) {
    const map = new Map(Object.entries(headers));
    return {
      get: (key) => map.get(key) || null,
    };
  }

  describe("basic functionality", () => {
    it("should return default values when Content-Length is not an integer", () => {
      const responseHeaders = createMockHeaders({
        "Content-Length": "not-a-number",
      });

      const result = validateRangeRequestCapabilities({
        responseHeaders,
        isHttp: true,
        rangeChunkSize: 65536,
        disableRange: false,
      });

      expect(result).toEqual({
        allowRangeRequests: false,
        suggestedLength: undefined,
      });
    });

    it("should return default values when Content-Length is null or missing", () => {
      const responseHeaders = createMockHeaders({});

      const result = validateRangeRequestCapabilities({
        responseHeaders,
        isHttp: true,
        rangeChunkSize: 65536,
        disableRange: false,
      });

      expect(result).toEqual({
        allowRangeRequests: false,
        suggestedLength: undefined,
      });
    });

    it("should return suggestedLength but no range requests when file size is valid", () => {
      const responseHeaders = createMockHeaders({
        "Content-Length": "100000",
      });

      const result = validateRangeRequestCapabilities({
        responseHeaders,
        isHttp: true,
        rangeChunkSize: 65536,
        disableRange: false,
      });

      expect(result).toEqual({
        allowRangeRequests: false,
        suggestedLength: 100000,
      });
    });
  });

  describe("file size constraints", () => {
    it("should not allow range requests when length <= 2 * rangeChunkSize", () => {
      const responseHeaders = createMockHeaders({
        "Content-Length": "131072", // 2 * 65536
      });

      const result = validateRangeRequestCapabilities({
        responseHeaders,
        isHttp: true,
        rangeChunkSize: 65536,
        disableRange: false,
      });

      expect(result.allowRangeRequests).toBe(false);
      expect(result.suggestedLength).toBe(131072);
    });

    it("should not allow range requests when length < 2 * rangeChunkSize", () => {
      const responseHeaders = createMockHeaders({
        "Content-Length": "131071", // just under 2 * 65536
      });

      const result = validateRangeRequestCapabilities({
        responseHeaders,
        isHttp: true,
        rangeChunkSize: 65536,
        disableRange: false,
      });

      expect(result.allowRangeRequests).toBe(false);
      expect(result.suggestedLength).toBe(131071);
    });

    it("should consider range requests when length > 2 * rangeChunkSize", () => {
      const responseHeaders = createMockHeaders({
        "Content-Length": "131073", // just over 2 * 65536
        "Accept-Ranges": "bytes",
        "Content-Encoding": "identity",
      });

      const result = validateRangeRequestCapabilities({
        responseHeaders,
        isHttp: true,
        rangeChunkSize: 65536,
        disableRange: false,
      });

      expect(result.allowRangeRequests).toBe(true);
      expect(result.suggestedLength).toBe(131073);
    });
  });

  describe("protocol and range disabling", () => {
    it("should not allow range requests when isHttp is false", () => {
      const responseHeaders = createMockHeaders({
        "Content-Length": "1000000",
        "Accept-Ranges": "bytes",
        "Content-Encoding": "identity",
      });

      const result = validateRangeRequestCapabilities({
        responseHeaders,
        isHttp: false,
        rangeChunkSize: 65536,
        disableRange: false,
      });

      expect(result.allowRangeRequests).toBe(false);
      expect(result.suggestedLength).toBe(1000000);
    });

    it("should not allow range requests when disableRange is true", () => {
      const responseHeaders = createMockHeaders({
        "Content-Length": "1000000",
        "Accept-Ranges": "bytes",
        "Content-Encoding": "identity",
      });

      const result = validateRangeRequestCapabilities({
        responseHeaders,
        isHttp: true,
        rangeChunkSize: 65536,
        disableRange: true,
      });

      expect(result.allowRangeRequests).toBe(false);
      expect(result.suggestedLength).toBe(1000000);
    });
  });

  describe("Accept-Ranges header", () => {
    it("should not allow range requests when Accept-Ranges is not 'bytes'", () => {
      const responseHeaders = createMockHeaders({
        "Content-Length": "1000000",
        "Accept-Ranges": "none",
        "Content-Encoding": "identity",
      });

      const result = validateRangeRequestCapabilities({
        responseHeaders,
        isHttp: true,
        rangeChunkSize: 65536,
        disableRange: false,
      });

      expect(result.allowRangeRequests).toBe(false);
      expect(result.suggestedLength).toBe(1000000);
    });

    it("should not allow range requests when Accept-Ranges is null", () => {
      const responseHeaders = createMockHeaders({
        "Content-Length": "1000000",
        "Content-Encoding": "identity",
      });

      const result = validateRangeRequestCapabilities({
        responseHeaders,
        isHttp: true,
        rangeChunkSize: 65536,
        disableRange: false,
      });

      expect(result.allowRangeRequests).toBe(false);
      expect(result.suggestedLength).toBe(1000000);
    });

    it("should allow range requests when Accept-Ranges is 'bytes'", () => {
      const responseHeaders = createMockHeaders({
        "Content-Length": "1000000",
        "Accept-Ranges": "bytes",
        "Content-Encoding": "identity",
      });

      const result = validateRangeRequestCapabilities({
        responseHeaders,
        isHttp: true,
        rangeChunkSize: 65536,
        disableRange: false,
      });

      expect(result.allowRangeRequests).toBe(true);
      expect(result.suggestedLength).toBe(1000000);
    });
  });

  describe("Content-Encoding header", () => {
    it("should not allow range requests when Content-Encoding is not 'identity'", () => {
      const responseHeaders = createMockHeaders({
        "Content-Length": "1000000",
        "Accept-Ranges": "bytes",
        "Content-Encoding": "gzip",
      });

      const result = validateRangeRequestCapabilities({
        responseHeaders,
        isHttp: true,
        rangeChunkSize: 65536,
        disableRange: false,
      });

      expect(result.allowRangeRequests).toBe(false);
      expect(result.suggestedLength).toBe(1000000);
    });

    it("should treat missing Content-Encoding as 'identity'", () => {
      const responseHeaders = createMockHeaders({
        "Content-Length": "1000000",
        "Accept-Ranges": "bytes",
      });

      const result = validateRangeRequestCapabilities({
        responseHeaders,
        isHttp: true,
        rangeChunkSize: 65536,
        disableRange: false,
      });

      expect(result.allowRangeRequests).toBe(true);
      expect(result.suggestedLength).toBe(1000000);
    });

    it("should allow range requests when Content-Encoding is 'identity'", () => {
      const responseHeaders = createMockHeaders({
        "Content-Length": "1000000",
        "Accept-Ranges": "bytes",
        "Content-Encoding": "identity",
      });

      const result = validateRangeRequestCapabilities({
        responseHeaders,
        isHttp: true,
        rangeChunkSize: 65536,
        disableRange: false,
      });

      expect(result.allowRangeRequests).toBe(true);
      expect(result.suggestedLength).toBe(1000000);
    });
  });

  describe("all conditions satisfied", () => {
    it("should allow range requests when all conditions are met", () => {
      const responseHeaders = createMockHeaders({
        "Content-Length": "1000000",
        "Accept-Ranges": "bytes",
        "Content-Encoding": "identity",
      });

      const result = validateRangeRequestCapabilities({
        responseHeaders,
        isHttp: true,
        rangeChunkSize: 65536,
        disableRange: false,
      });

      expect(result).toEqual({
        allowRangeRequests: true,
        suggestedLength: 1000000,
      });
    });
  });

  describe("rangeChunkSize validation", () => {
    let originalPDFJSDev;

    beforeEach(() => {
      originalPDFJSDev = global.PDFJSDev;
    });

    afterEach(() => {
      global.PDFJSDev = originalPDFJSDev;
    });

    it("should validate rangeChunkSize is positive integer when PDFJSDev is undefined", () => {
      delete global.PDFJSDev;

      // Valid case should not throw
      const responseHeaders = createMockHeaders({});
      expect(() => {
        validateRangeRequestCapabilities({
          responseHeaders,
          isHttp: true,
          rangeChunkSize: 65536,
          disableRange: false,
        });
      }).not.toThrow();

      // Invalid cases should throw
      expect(() => {
        validateRangeRequestCapabilities({
          responseHeaders,
          isHttp: true,
          rangeChunkSize: 0,
          disableRange: false,
        });
      }).toThrow("rangeChunkSize must be an integer larger than zero.");

      expect(() => {
        validateRangeRequestCapabilities({
          responseHeaders,
          isHttp: true,
          rangeChunkSize: -1,
          disableRange: false,
        });
      }).toThrow("rangeChunkSize must be an integer larger than zero.");

      expect(() => {
        validateRangeRequestCapabilities({
          responseHeaders,
          isHttp: true,
          rangeChunkSize: 3.14,
          disableRange: false,
        });
      }).toThrow("rangeChunkSize must be an integer larger than zero.");
    });

    it("should validate rangeChunkSize is positive integer when PDFJSDev.test('TESTING') returns true", () => {
      global.PDFJSDev = {
        test: jest.fn().mockReturnValue(true),
      };

      const responseHeaders = createMockHeaders({});

      // Valid case should not throw
      expect(() => {
        validateRangeRequestCapabilities({
          responseHeaders,
          isHttp: true,
          rangeChunkSize: 65536,
          disableRange: false,
        });
      }).not.toThrow();

      // Invalid case should throw
      expect(() => {
        validateRangeRequestCapabilities({
          responseHeaders,
          isHttp: true,
          rangeChunkSize: 0,
          disableRange: false,
        });
      }).toThrow("rangeChunkSize must be an integer larger than zero.");
    });

    it("should not validate rangeChunkSize when PDFJSDev.test('TESTING') returns false", () => {
      global.PDFJSDev = {
        test: jest.fn().mockReturnValue(false),
      };

      const responseHeaders = createMockHeaders({});

      // Even invalid rangeChunkSize should not throw when not in TESTING mode
      expect(() => {
        validateRangeRequestCapabilities({
          responseHeaders,
          isHttp: true,
          rangeChunkSize: 0,
          disableRange: false,
        });
      }).not.toThrow();

      expect(() => {
        validateRangeRequestCapabilities({
          responseHeaders,
          isHttp: true,
          rangeChunkSize: -1,
          disableRange: false,
        });
      }).not.toThrow();
    });
  });
});

