import { extractFilenameFromHeader } from "../../../src/display/network_utils.js";
import { describe, it, expect } from "@jest/globals";

describe("extractFilenameFromHeader", () => {
  it("should return null when no Content-Disposition header", () => {
    const headers = new Headers();
    expect(extractFilenameFromHeader(headers)).toBe(null);
  });

  it("should return null when Content-Disposition header exists but no filename", () => {
    const headers = new Headers();
    headers.set("Content-Disposition", "inline");
    expect(extractFilenameFromHeader(headers)).toBe(null);
  });

  it("should return null when filename is not a PDF file", () => {
    const headers = new Headers();
    headers.set("Content-Disposition", 'attachment; filename="document.txt"');
    expect(extractFilenameFromHeader(headers)).toBe(null);
  });

  it("should return filename when valid PDF filename in Content-Disposition", () => {
    const headers = new Headers();
    headers.set("Content-Disposition", 'attachment; filename="document.pdf"');
    expect(extractFilenameFromHeader(headers)).toBe("document.pdf");
  });

  it("should handle filename without quotes", () => {
    const headers = new Headers();
    headers.set("Content-Disposition", "attachment; filename=document.pdf");
    expect(extractFilenameFromHeader(headers)).toBe("document.pdf");
  });

  it("should handle filename with spaces", () => {
    const headers = new Headers();
    headers.set("Content-Disposition", 'attachment; filename="my document.pdf"');
    expect(extractFilenameFromHeader(headers)).toBe("my document.pdf");
  });

  it("should decode URL-encoded filename with percent signs", () => {
    const headers = new Headers();
    headers.set("Content-Disposition", 'attachment; filename="document%20file.pdf"');
    expect(extractFilenameFromHeader(headers)).toBe("document file.pdf");
  });

  it("should handle malformed URL encoding gracefully", () => {
    const headers = new Headers();
    headers.set("Content-Disposition", 'attachment; filename="document%2.pdf"');
    // Should not crash, invalid %2 should be handled by decodeURIComponent try/catch
    // decodeURIComponent fails on %2, so filename stays as document%2.pdf
    // but isPdfFile still returns true because it ends with .pdf
    expect(extractFilenameFromHeader(headers)).toBe("document%2.pdf");
  });

  it("should handle case-insensitive .pdf extension", () => {
    const headers = new Headers();
    headers.set("Content-Disposition", 'attachment; filename="DOCUMENT.PDF"');
    expect(extractFilenameFromHeader(headers)).toBe("DOCUMENT.PDF");
  });

  it("should handle mixed case .pdf extension", () => {
    const headers = new Headers();
    headers.set("Content-Disposition", 'attachment; filename="Document.PdF"');
    expect(extractFilenameFromHeader(headers)).toBe("Document.PdF");
  });

  it("should return null for files that look like PDF but have wrong extension", () => {
    const headers = new Headers();
    headers.set("Content-Disposition", 'attachment; filename="document.pdf.txt"');
    expect(extractFilenameFromHeader(headers)).toBe(null);
  });

  it("should handle filename* parameter with encoding", () => {
    const headers = new Headers();
    headers.set("Content-Disposition", "attachment; filename*=UTF-8''document.pdf");
    expect(extractFilenameFromHeader(headers)).toBe("document.pdf");
  });

  it("should handle filename with UTF-8 characters", () => {
    const headers = new Headers();
    headers.set("Content-Disposition", 'attachment; filename="café.pdf"');
    expect(extractFilenameFromHeader(headers)).toBe("café.pdf");
  });

  it("should prioritize filename* over filename", () => {
    const headers = new Headers();
    headers.set("Content-Disposition", 'attachment; filename="wrong.txt"; filename*=UTF-8\'\'document.pdf');
    expect(extractFilenameFromHeader(headers)).toBe("document.pdf");
  });

  it("should return null when getFilenameFromContentDispositionHeader returns empty string", () => {
    const headers = new Headers();
    // Empty Content-Disposition value might cause empty string
    headers.set("Content-Disposition", "");
    expect(extractFilenameFromHeader(headers)).toBe(null);
  });

  it("should handle filename with multiple percent-encoded sections", () => {
    const headers = new Headers();
    headers.set("Content-Disposition", 'attachment; filename="document%20with%20spaces.pdf"');
    expect(extractFilenameFromHeader(headers)).toBe("document with spaces.pdf");
  });

  it("should handle filename with plus signs (not URL encoded)", () => {
    const headers = new Headers();
    headers.set("Content-Disposition", 'attachment; filename="document+plus.pdf"');
    expect(extractFilenameFromHeader(headers)).toBe("document+plus.pdf");
  });

  it("should handle filename with actual plus sign that should be decoded as space", () => {
    const headers = new Headers();
    // decodeURIComponent doesn't decode + to space, that's for application/x-www-form-urlencoded
    // So + stays as +
    headers.set("Content-Disposition", 'attachment; filename="document+plus.pdf"');
    expect(extractFilenameFromHeader(headers)).toBe("document+plus.pdf");
  });

  it("should handle filename with encoded plus sign (%2B)", () => {
    const headers = new Headers();
    headers.set("Content-Disposition", 'attachment; filename="document%2Bplus.pdf"');
    expect(extractFilenameFromHeader(headers)).toBe("document+plus.pdf");
  });

  it("should handle attachment with filename", () => {
    const headers = new Headers();
    headers.set("Content-Disposition", 'attachment; filename="test.pdf"');
    expect(extractFilenameFromHeader(headers)).toBe("test.pdf");
  });

  it("should handle inline with filename", () => {
    const headers = new Headers();
    headers.set("Content-Disposition", 'inline; filename="test.pdf"');
    expect(extractFilenameFromHeader(headers)).toBe("test.pdf");
  });

  it("should return null for non-PDF even with valid Content-Disposition", () => {
    const headers = new Headers();
    headers.set("Content-Disposition", 'attachment; filename="image.png"');
    expect(extractFilenameFromHeader(headers)).toBe(null);
  });

  it("should handle filename in single quotes", () => {
    const headers = new Headers();
    headers.set("Content-Disposition", "attachment; filename='document.pdf'");
    // Single quotes not valid per RFC 2616, getFilenameFromContentDispositionHeader returns "'document.pdf'"
    // isPdfFile("'document.pdf'") returns false because it ends with ".pdf'", not ".pdf"
    expect(extractFilenameFromHeader(headers)).toBe(null);
  });

  it("should handle filename with escaped quotes", () => {
    const headers = new Headers();
    headers.set("Content-Disposition", 'attachment; filename="\"quoted\".pdf"');
    // getFilenameFromContentDispositionHeader might return empty string for malformed quotes
    expect(extractFilenameFromHeader(headers)).toBe(null);
  });

  it("should handle responseHeaders without get method", () => {
    // Function expects Headers object with get method
    // Without it, it throws TypeError
    const badHeaders = {};
    expect(() => extractFilenameFromHeader(badHeaders)).toThrow(TypeError);
  });

  it("should handle responseHeaders.get returning non-string", () => {
    const headers = new Headers();
    // Mock get method to return non-string
    headers.get = () => 123;
    // getFilenameFromContentDispositionHeader(123) returns empty string
    // isPdfFile("") returns false
    expect(extractFilenameFromHeader(headers)).toBe(null);
  });
});

