import { describe, it, expect, beforeEach, jest } from "@jest/globals";

// Re-create the functions from the source file for testing
// This mimics the actual implementation in contentscript.js
function createTestFunctions() {
  const VIEWER_URL = "chrome-extension://test-id/content/web/viewer.html";

  function getViewerURL(pdf_url) {
    return VIEWER_URL + "?file=" + encodeURIComponent(pdf_url);
  }

  function getEmbeddedViewerURL(path) {
    const fragmentMatch = /^([^#]*)(#.*)?$/.exec(path);
    path = fragmentMatch[1];
    const fragment = fragmentMatch[2] || "";

    // Create anchor element to resolve relative path
    const a = document.createElement("a");
    a.href = document.baseURI || "https://example.com/";
    a.href = path;
    path = a.href;
    return getViewerURL(path) + fragment;
  }

  // Display the PDF Viewer in an <embed>.
  function updateEmbedElement(elem) {
    if (elem.type === "text/html" && elem.src.lastIndexOf(VIEWER_URL, 0) === 0) {
      // The viewer is already shown.
      return;
    }
    // The <embed> tag needs to be removed and re-inserted before any src changes
    // are effective.
    var parentNode = elem.parentNode;
    var nextSibling = elem.nextSibling;
    if (parentNode) {
      elem.remove();
    }
    elem.type = "text/html";
    elem.src = getEmbeddedViewerURL(elem.src);

    if (parentNode) {
      // Suppress linter warning: insertBefore is preferable to
      // nextSibling.before(elem) because nextSibling may be null.
      // eslint-disable-next-line unicorn/prefer-modern-dom-apis
      parentNode.insertBefore(elem, nextSibling);
    }
  }

  return { updateEmbedElement, getEmbeddedViewerURL, getViewerURL };
}

