// Mock OffscreenCanvas and CanvasRenderingContext2D
class MockOffscreenCanvas {
  constructor(width, height) {
    this.width = width;
    this.height = height;
    this._context = null;
  }

  getContext(contextType, options = {}) {
    if (contextType === "2d") {
      if (!this._context) {
        this._context = new MockCanvasRenderingContext2D(
          this.width,
          this.height,
          options
        );
      }
      return this._context;
    }
    return null;
  }
}

class MockCanvasRenderingContext2D {
  constructor(width, height, options) {
    this.width = width;
    this.height = height;
    this.options = options;
    this.font = "";
    this.filter = "";
    this.fillStyle = "";
    this._imageData = null;
    this._measureTextResults = {};
  }

  measureText(text) {
    // Return mock measurements based on text
    if (!this._measureTextResults[text]) {
      // Create realistic mock measurements
      const fontSize = 200; // Default fontSize from the function
      const textWidth = text.length * fontSize * 0.6; // Approximate width
      this._measureTextResults[text] = {
        actualBoundingBoxLeft: -textWidth / 2,
        actualBoundingBoxRight: textWidth / 2,
        actualBoundingBoxAscent: fontSize * 0.8,
        actualBoundingBoxDescent: fontSize * 0.2,
        fontBoundingBoxAscent: fontSize,
        fontBoundingBoxDescent: fontSize * 0.3,
        width: textWidth,
      };
    }
    return this._measureTextResults[text];
  }

  fillRect(x, y, width, height) {
    // Mock implementation
  }

  fillText(text, x, y) {
    // Mock implementation - we'll store what would be drawn
    this._lastText = { text, x, y };
  }

  getImageData(x, y, width, height) {
    if (!this._imageData) {
      // Create mock image data with white background and black text
      const dataSize = width * height * 4;
      const data = new Uint8ClampedArray(dataSize);

      // Fill with white (255 for all RGBA)
      for (let i = 0; i < dataSize; i += 4) {
        data[i] = 255; // R
        data[i + 1] = 255; // G
        data[i + 2] = 255; // B
        data[i + 3] = 255; // A
      }

      // Add some black pixels to simulate text (middle area)
      const centerX = Math.floor(width / 2);
      const centerY = Math.floor(height / 2);
      const textHeight = Math.floor(height * 0.2);
      const textWidth = Math.floor(width * 0.6);

      for (let i = centerY - textHeight; i < centerY + textHeight; i++) {
        for (let j = centerX - textWidth; j < centerX + textWidth; j++) {
          if (i >= 0 && i < height && j >= 0 && j < width) {
            const index = (i * width + j) * 4;
            data[index] = 0; // R - black
            data[index + 1] = 0; // G - black
            data[index + 2] = 0; // B - black
            data[index + 3] = 255; // A - fully opaque
          }
        }
      }

      this._imageData = {
        data,
        width,
        height,
      };
    }
    return this._imageData;
  }
}

