import { beforeEach, describe, expect, it, jest } from "@jest/globals";
import { SignatureExtractor } from "../../../../../src/display/editor/drawers/signaturedraw.js";

// Mock OffscreenCanvas and CanvasRenderingContext2D (reused from existing test)
class MockOffscreenCanvas {
  constructor(width, height) {
    this.width = width;
    this.height = height;
    this._context = null;
  }

  getContext(contextType, options = {}) {
    if (contextType === "2d") {
      if (!this._context) {
        this._context = new MockCanvasRenderingContext2D(
          this.width,
          this.height,
          options
        );
      }
      return this._context;
    }
    return null;
  }

  transferToImageBitmap() {
    // Return a mock ImageBitmap
    return {
      width: this.width,
      height: this.height,
      close: jest.fn(),
    };
  }
}

class MockCanvasRenderingContext2D {
  constructor(width, height, options) {
    this.width = width;
    this.height = height;
    this.options = options;
    this.font = "";
    this.filter = "";
    this.fillStyle = "";
    this._imageData = null;
    this._drawnImages = [];
  }

  fillRect(x, y, width, height) {
    // Mock implementation
  }

  drawImage(image, sx, sy, sWidth, sHeight, dx, dy, dWidth, dHeight) {
    // Store what was drawn for verification
    this._drawnImages.push({
      image,
      sx,
      sy,
      sWidth,
      sHeight,
      dx,
      dy,
      dWidth,
      dHeight,
    });
  }

  getImageData(x, y, width, height) {
    // Create mock image data with some pattern for testing
    // Create fresh each time since dimensions may change
    const dataSize = width * height * 4;
    const data = new Uint8ClampedArray(dataSize);

    // Create a simple pattern: darker in the center, lighter at edges
    // But ensure we have some variation for thresholding
    for (let i = 0; i < height; i++) {
      for (let j = 0; j < width; j++) {
        const index = (i * width + j) * 4;
        // Simple pattern: checkerboard or gradient
        const intensity = (i + j) % 2 === 0 ? 100 : 200;
        data[index] = intensity; // R
        data[index + 1] = intensity; // G
        data[index + 2] = intensity; // B
        data[index + 3] = 255; // A
      }
    }

    return {
      data,
      width,
      height,
    };
  }
}

// Mock ImageBitmap
class MockImageBitmap {
  constructor(width, height) {
    this.width = width;
    this.height = height;
    this.close = jest.fn();
  }
}

