import { describe, expect, it } from "@jest/globals";
import { MurmurHash3_64 } from "../../../src/shared/murmurhash3.js";

describe("MurmurHash3_64.update", () => {
  describe("string input", () => {
    it("should handle ASCII strings correctly", () => {
      const hasher = new MurmurHash3_64();
      hasher.update("test");

      // Check that internal state is updated
      expect(hasher.h1).toBeDefined();
      expect(hasher.h2).toBeDefined();
      expect(typeof hasher.h1).toBe("number");
      expect(typeof hasher.h2).toBe("number");
    });

    it("should handle Unicode strings", () => {
      const hasher = new MurmurHash3_64();
      hasher.update("test café テスト");

      expect(hasher.h1).toBeDefined();
      expect(hasher.h2).toBeDefined();
    });

    it("should handle empty string", () => {
      const hasher = new MurmurHash3_64();
      const initialH1 = hasher.h1;
      const initialH2 = hasher.h2;

      hasher.update("");

      // Empty string should not change the hash
      expect(hasher.h1).toBe(initialH1);
      expect(hasher.h2).toBe(initialH2);
    });

    it("should handle single character string", () => {
      const hasher = new MurmurHash3_64();
      hasher.update("a");

      expect(hasher.h1).toBeDefined();
      expect(hasher.h2).toBeDefined();
    });

    it("should handle string with only ASCII characters <= 0xff", () => {
      const hasher = new MurmurHash3_64();
      hasher.update("abc");

      expect(hasher.h1).toBeDefined();
      expect(hasher.h2).toBeDefined();
    });

    it("should handle string with characters > 0xff", () => {
      const hasher = new MurmurHash3_64();
      hasher.update(" café ");

      expect(hasher.h1).toBeDefined();
      expect(hasher.h2).toBeDefined();
    });
  });

  describe("TypedArray input", () => {
    it("should handle Uint8Array", () => {
      const hasher = new MurmurHash3_64();
      const data = new Uint8Array([1, 2, 3, 4, 5]);
      hasher.update(data);

      expect(hasher.h1).toBeDefined();
      expect(hasher.h2).toBeDefined();
    });

    it("should handle Uint32Array", () => {
      const hasher = new MurmurHash3_64();
      const data = new Uint32Array([0x12345678, 0x9abcdef0]);
      hasher.update(data);

      expect(hasher.h1).toBeDefined();
      expect(hasher.h2).toBeDefined();
    });

    it("should handle Int8Array", () => {
      const hasher = new MurmurHash3_64();
      const data = new Int8Array([-1, 0, 1, 127, -128]);
      hasher.update(data);

      expect(hasher.h1).toBeDefined();
      expect(hasher.h2).toBeDefined();
    });

    it("should handle empty TypedArray", () => {
      const hasher = new MurmurHash3_64();
      const initialH1 = hasher.h1;
      const initialH2 = hasher.h2;
      const data = new Uint8Array(0);

      hasher.update(data);

      // Empty array should not change the hash
      expect(hasher.h1).toBe(initialH1);
      expect(hasher.h2).toBe(initialH2);
    });

    it("should handle ArrayBuffer view with offset", () => {
      const hasher = new MurmurHash3_64();
      const buffer = new ArrayBuffer(10);
      const view = new Uint8Array(buffer, 2, 5);

      // Fill with some data
      for (let i = 0; i < view.length; i++) {
        view[i] = i * 10;
      }

      hasher.update(view);

      expect(hasher.h1).toBeDefined();
      expect(hasher.h2).toBeDefined();
    });
  });

  describe("error cases", () => {
    it("should throw error for non-string, non-TypedArray input", () => {
      const hasher = new MurmurHash3_64();

      expect(() => {
        hasher.update(123);
      }).toThrow("Invalid data format, must be a string or TypedArray.");

      expect(() => {
        hasher.update({});
      }).toThrow("Invalid data format, must be a string or TypedArray.");

      expect(() => {
        hasher.update(null);
      }).toThrow("Invalid data format, must be a string or TypedArray.");

      expect(() => {
        hasher.update(undefined);
      }).toThrow("Invalid data format, must be a string or TypedArray.");

      expect(() => {
        hasher.update([1, 2, 3]); // Regular array, not TypedArray
      }).toThrow("Invalid data format, must be a string or TypedArray.");
    });
  });

  describe("hash state updates", () => {
    it("should update internal state incrementally", () => {
      const hasher1 = new MurmurHash3_64();
      const hasher2 = new MurmurHash3_64();

      // Update hasher1 with combined string
      hasher1.update("hello");
      hasher1.update("world");

      // Update hasher2 with concatenated string
      hasher2.update("helloworld");

      // Results should be different because update is stateful
      expect(hasher1.h1).not.toBe(hasher2.h1);
      expect(hasher1.h2).not.toBe(hasher2.h2);
    });

    it("should produce same hash for same input with same seed", () => {
      const seed = 0x12345678;
      const hasher1 = new MurmurHash3_64(seed);
      const hasher2 = new MurmurHash3_64(seed);

      hasher1.update("test input");
      hasher2.update("test input");

      expect(hasher1.h1).toBe(hasher2.h1);
      expect(hasher1.h2).toBe(hasher2.h2);
    });

    it("should produce different hash for same input with different seed", () => {
      const hasher1 = new MurmurHash3_64(0x11111111);
      const hasher2 = new MurmurHash3_64(0x22222222);

      hasher1.update("test input");
      hasher2.update("test input");

      expect(hasher1.h1).not.toBe(hasher2.h1);
      expect(hasher1.h2).not.toBe(hasher2.h2);
    });

    it("should handle multiple updates correctly", () => {
      const hasher = new MurmurHash3_64();
      const initialStateH1 = hasher.h1;
      const initialStateH2 = hasher.h2;

      hasher.update("first");
      const afterFirstH1 = hasher.h1;
      const afterFirstH2 = hasher.h2;

      hasher.update("second");
      const afterSecondH1 = hasher.h1;
      const afterSecondH2 = hasher.h2;

      // Each update should change the state
      expect(afterFirstH1).not.toBe(initialStateH1);
      expect(afterFirstH2).not.toBe(initialStateH2);
      expect(afterSecondH1).not.toBe(afterFirstH1);
      expect(afterSecondH2).not.toBe(afterFirstH2);
    });
  });

  describe("edge cases for block processing", () => {
    it("should handle data that fits exactly in 4-byte blocks", () => {
      const hasher = new MurmurHash3_64();
      // 8 bytes = exactly 2 blocks
      const data = new Uint8Array([1, 2, 3, 4, 5, 6, 7, 8]);
      hasher.update(data);

      expect(hasher.h1).toBeDefined();
      expect(hasher.h2).toBeDefined();
    });

    it("should handle data with tail length 1", () => {
      const hasher = new MurmurHash3_64();
      // 5 bytes = 1 block + 1 tail byte
      const data = new Uint8Array([1, 2, 3, 4, 5]);
      hasher.update(data);

      expect(hasher.h1).toBeDefined();
      expect(hasher.h2).toBeDefined();
    });

    it("should handle data with tail length 2", () => {
      const hasher = new MurmurHash3_64();
      // 6 bytes = 1 block + 2 tail bytes
      const data = new Uint8Array([1, 2, 3, 4, 5, 6]);
      hasher.update(data);

      expect(hasher.h1).toBeDefined();
      expect(hasher.h2).toBeDefined();
    });

    it("should handle data with tail length 3", () => {
      const hasher = new MurmurHash3_64();
      // 7 bytes = 1 block + 3 tail bytes
      const data = new Uint8Array([1, 2, 3, 4, 5, 6, 7]);
      hasher.update(data);

      expect(hasher.h1).toBeDefined();
      expect(hasher.h2).toBeDefined();
    });

    it("should handle large data input", () => {
      const hasher = new MurmurHash3_64();
      // Create a large string
      const largeString = "a".repeat(1000);
      hasher.update(largeString);

      expect(hasher.h1).toBeDefined();
      expect(hasher.h2).toBeDefined();
    });

    it("should handle string with mixed ASCII and Unicode characters", () => {
      const hasher = new MurmurHash3_64();
      const mixedString = "ABC café 123 テスト xyz";
      hasher.update(mixedString);

      expect(hasher.h1).toBeDefined();
      expect(hasher.h2).toBeDefined();
    });
  });

  describe("consistency with hexdigest", () => {
    it("should produce consistent hexdigest after update", () => {
      const hasher = new MurmurHash3_64();
      hasher.update("test data");
      const hex1 = hasher.hexdigest();

      // Update with more data
      hasher.update(" more data");
      const hex2 = hasher.hexdigest();

      // Hexdigests should be different after update
      expect(hex1).not.toBe(hex2);
      expect(typeof hex1).toBe("string");
      expect(typeof hex2).toBe("string");
      expect(hex1.length).toBe(16); // 8 bytes = 16 hex chars
      expect(hex2.length).toBe(16);
    });
  });
});

