import { describe, it, expect } from "@jest/globals";

// InfoProxyHandler is an internal class not exported from doc.js
// We'll recreate it exactly as in the source for testing
class InfoProxyHandler {
  static get(obj, prop) {
    return obj[prop.toLowerCase()];
  }
}

describe("InfoProxyHandler.get", () => {
  describe("basic functionality", () => {
    it("should retrieve property by converting prop to lowercase", () => {
      const obj = { title: "Document Title", author: "John Doe" };
      const result = InfoProxyHandler.get(obj, "TITLE");
      expect(result).toBe("Document Title");
    });

    it("should handle mixed case property names", () => {
      const obj = { title: "Document Title", author: "John Doe", subject: "Test" };
      const result = InfoProxyHandler.get(obj, "TiTlE");
      expect(result).toBe("Document Title");
    });

    it("should handle all lowercase property names", () => {
      const obj = { title: "Document Title", author: "John Doe" };
      const result = InfoProxyHandler.get(obj, "title");
      expect(result).toBe("Document Title");
    });

    it("should handle all uppercase property names", () => {
      const obj = { title: "Document Title", author: "John Doe" };
      const result = InfoProxyHandler.get(obj, "AUTHOR");
      expect(result).toBe("John Doe");
    });
  });

  describe("edge cases", () => {
    it("should return undefined for non-existent properties", () => {
      const obj = { title: "Document Title" };
      const result = InfoProxyHandler.get(obj, "NONEXISTENT");
      expect(result).toBeUndefined();
    });

    it("should handle empty string property", () => {
      const obj = { "": "Empty property" };
      const result = InfoProxyHandler.get(obj, "");
      expect(result).toBe("Empty property");
    });

    it("should handle numeric property names", () => {
      const obj = { 123: "Numeric property" };
      const result = InfoProxyHandler.get(obj, "123");
      expect(result).toBe("Numeric property");
    });

    it("should handle property names with special characters", () => {
      const obj = { "special-prop": "Special property" };
      const result = InfoProxyHandler.get(obj, "SPECIAL-PROP");
      expect(result).toBe("Special property");
    });

    it("should handle property names with spaces", () => {
      const obj = { "property with spaces": "Value with spaces" };
      const result = InfoProxyHandler.get(obj, "PROPERTY WITH SPACES");
      expect(result).toBe("Value with spaces");
    });

    it("should handle properties with null or undefined values", () => {
      const obj = { nullprop: null, undefinedprop: undefined };
      const nullResult = InfoProxyHandler.get(obj, "NULLPROP");
      const undefinedResult = InfoProxyHandler.get(obj, "UNDEFINEDPROP");

      expect(nullResult).toBeNull();
      expect(undefinedResult).toBeUndefined();
    });

    it("should handle inherited properties", () => {
      const parent = { inherited: "Parent property" };
      const child = Object.create(parent);
      child.own = "Own property";

      const result = InfoProxyHandler.get(child, "INHERITED");
      expect(result).toBe("Parent property");

      const ownResult = InfoProxyHandler.get(child, "OWN");
      expect(ownResult).toBe("Own property");
    });

    it("should handle properties with getters", () => {
      const obj = {};
      Object.defineProperty(obj, "computed", {
        get() {
          return "Computed value";
        },
        enumerable: true,
        configurable: true
      });

      const result = InfoProxyHandler.get(obj, "COMPUTED");
      expect(result).toBe("Computed value");
    });

    it("should handle Symbol properties", () => {
      const sym = Symbol("test");
      const obj = { [sym]: "Symbol value", regular: "Regular value" };

      // Note: Symbols as property names are not converted to strings
      // When prop is a Symbol, prop.toLowerCase() will throw
      // This test case might not be valid for actual usage
      expect(() => InfoProxyHandler.get(obj, sym)).toThrow();
    });
  });

  describe("property case sensitivity normalization", () => {
    it("should match properties regardless of case variations", () => {
      // Target object should have lowercase keys as per the actual usage
      const obj = { 
        title: "Document title",
        subject: "Document subject",
        author: "Document author",
        keywords: "Document keywords" 
      };

      expect(InfoProxyHandler.get(obj, "TITLE")).toBe("Document title");
      expect(InfoProxyHandler.get(obj, "title")).toBe("Document title");
      expect(InfoProxyHandler.get(obj, "TiTlE")).toBe("Document title");

      expect(InfoProxyHandler.get(obj, "SUBJECT")).toBe("Document subject");
      expect(InfoProxyHandler.get(obj, "subject")).toBe("Document subject");

      expect(InfoProxyHandler.get(obj, "AUTHOR")).toBe("Document author");
      expect(InfoProxyHandler.get(obj, "author")).toBe("Document author");

      expect(InfoProxyHandler.get(obj, "KEYWORDS")).toBe("Document keywords");
      expect(InfoProxyHandler.get(obj, "keywords")).toBe("Document keywords");
    });

    it("should handle property names with varying Unicode case", () => {
      const obj = { "straße": "German street" };
      // Note: "straße".toLowerCase() === "straße" (no change for German sharp s)
      // "STRASSE".toLowerCase() === "strasse"
      // So obj["strasse"] is undefined
      // This test should use the actual lowercase key
      const obj2 = { "strasse": "German street alternative" };
      const result = InfoProxyHandler.get(obj2, "STRASSE");
      expect(result).toBe("German street alternative");
    });
  });

  describe("object types", () => {
    it("should work with plain objects", () => {
      const obj = { key: "value" };
      const result = InfoProxyHandler.get(obj, "KEY");
      expect(result).toBe("value");
    });

    it("should work with array objects", () => {
      const arr = ["zero", "one", "two"];
      const result = InfoProxyHandler.get(arr, "0");
      expect(result).toBe("zero");
    });

    it("should work with Date objects", () => {
      const date = new Date();
      date.customprop = "Custom property"; // lowercase key
      const result = InfoProxyHandler.get(date, "CUSTOMPROP");
      expect(result).toBe("Custom property");
    });

    it("should work with function objects", () => {
      function testFunc() {}
      testFunc.customprop = "Function property"; // lowercase key
      const result = InfoProxyHandler.get(testFunc, "CUSTOMPROP");
      expect(result).toBe("Function property");
    });

    it("should work with class instance objects", () => {
      class TestClass {
        constructor(value) {
          this.value = value;
        }
      }
      const instance = new TestClass("Instance value");
      const result = InfoProxyHandler.get(instance, "VALUE");
      expect(result).toBe("Instance value");
    });
  });

  describe("performance considerations", () => {
    it("should handle many properties efficiently", () => {
      const obj = {};
      for (let i = 0; i < 1000; i++) {
        obj[`property${i}`] = `value${i}`;
      }

      expect(InfoProxyHandler.get(obj, "PROPERTY0")).toBe("value0");
      expect(InfoProxyHandler.get(obj, "PROPERTY500")).toBe("value500");
      expect(InfoProxyHandler.get(obj, "PROPERTY999")).toBe("value999");
    });
  });
});

