import { Doc } from "../../../src/scripting_api/doc.js";
import { PrintParams } from "../../../src/scripting_api/print_params.js";
import { describe, it, expect, beforeEach, jest } from "@jest/globals";

describe("Doc.print", () => {
  let doc;
  let mockSend;

  beforeEach(() => {
    mockSend = jest.fn();
    doc = new Doc({
      send: mockSend,
      numPages: 10,
      pageNum: 0,
      Author: "Test Author",
      Creator: "Test Creator",
      filename: "test.pdf",
      filesize: 1024,
      Keywords: "test,keywords",
      layout: "SinglePage",
      Producer: "Test Producer",
      Subject: "Test Subject",
      Title: "Test Document",
      URL: "http://example.com/test.pdf",
      baseURL: "http://example.com/",
      metadata: "metadata",
      zoom: 100,
      actions: {},
      globalEval: () => {},
      authors: ["Test Author"],
      Trapped: "Unknown",
    });
  });

  describe("basic functionality", () => {
    it("should send print command with default parameters when user activation is true", () => {
      doc._userActivation = true;
      doc.print();
      expect(mockSend).toHaveBeenCalledWith({ command: "print", start: 0, end: 0 });
    });

    it("should handle custom start and end page numbers", () => {
      doc._userActivation = true;
      doc.print(true, 2, 5);
      expect(mockSend).toHaveBeenCalledWith({ command: "print", start: 2, end: 5 });
    });

    it("should handle negative end page as 0 (print all)", () => {
      doc._userActivation = true;
      doc.print(true, 0, -5);
      expect(mockSend).toHaveBeenCalledWith({ command: "print", start: 0, end: 0 });
    });

    it("should truncate floating point page numbers", () => {
      doc._userActivation = true;
      doc.print(true, 2.7, 5.3);
      expect(mockSend).toHaveBeenCalledWith({ command: "print", start: 2, end: 5 });
    });

    it("should handle non-number start page as 0", () => {
      doc._userActivation = true;
      doc.print(true, "not a number", 5);
      expect(mockSend).toHaveBeenCalledWith({ command: "print", start: 0, end: 5 });
    });

    it("should handle non-number end page as -1", () => {
      doc._userActivation = true;
      doc.print(true, 0, "not a number");
      expect(mockSend).toHaveBeenCalledWith({ command: "print", start: 0, end: -1 });
    });

    it("should reset user activation after printing", () => {
      doc._userActivation = true;
      doc.print();
      expect(doc._userActivation).toBe(false);
    });
  });

  describe("object parameter handling", () => {
    it("should extract parameters from object when first argument is an object", () => {
      doc._userActivation = true;
      const params = {
        bUI: false,
        nStart: 3,
        nEnd: 7,
        bSilent: true,
        bShrinkToFit: true,
        bPrintAsImage: true,
        bReverse: true,
        bAnnotations: false,
        printParams: null,
      };
      doc.print(params);
      expect(mockSend).toHaveBeenCalledWith({ command: "print", start: 3, end: 7 });
    });

    it("should handle printParams object for start and end pages", () => {
      doc._userActivation = true;
      const printParams = new PrintParams({ lastPage: 10 });
      printParams.firstPage = 2;
      printParams.lastPage = 8;
      doc.print(true, 0, -1, false, false, false, false, true, printParams);
      expect(mockSend).toHaveBeenCalledWith({ command: "print", start: 2, end: 8 });
    });

    it("should handle object parameter with printParams property", () => {
      doc._userActivation = true;
      const printParams = new PrintParams({ lastPage: 10 });
      printParams.firstPage = 1;
      printParams.lastPage = 5;
      const params = {
        bUI: true,
        nStart: 0,
        nEnd: -1,
        bSilent: false,
        bShrinkToFit: false,
        bPrintAsImage: false,
        bReverse: false,
        bAnnotations: true,
        printParams,
      };
      doc.print(params);
      expect(mockSend).toHaveBeenCalledWith({ command: "print", start: 1, end: 5 });
    });
  });

  describe("edge cases", () => {
    it("should not send print command when printing is disabled", () => {
      doc._userActivation = true;
      doc._disablePrinting = true;
      doc.print();
      expect(mockSend).not.toHaveBeenCalled();
      expect(doc._userActivation).toBe(true); // Should not reset when disabled
    });

    it("should not send print command when user activation is false", () => {
      doc._userActivation = false;
      doc.print();
      expect(mockSend).not.toHaveBeenCalled();
    });

    it("should not send print command when both printing disabled and no user activation", () => {
      doc._userActivation = false;
      doc._disablePrinting = true;
      doc.print();
      expect(mockSend).not.toHaveBeenCalled();
    });

    it("should handle start page less than 0 by setting to 0", () => {
      doc._userActivation = true;
      doc.print(true, -5, 10);
      expect(mockSend).toHaveBeenCalledWith({ command: "print", start: 0, end: 10 });
    });

    it("should handle end page less than 0 by setting to 0 (print all)", () => {
      doc._userActivation = true;
      doc.print(true, 0, -10);
      expect(mockSend).toHaveBeenCalledWith({ command: "print", start: 0, end: 0 });
    });

    it("should handle start page as null", () => {
      doc._userActivation = true;
      doc.print(true, null, 5);
      expect(mockSend).toHaveBeenCalledWith({ command: "print", start: 0, end: 5 });
    });

    it("should handle end page as null", () => {
      doc._userActivation = true;
      doc.print(true, 0, null);
      expect(mockSend).toHaveBeenCalledWith({ command: "print", start: 0, end: -1 });
    });

    it("should handle start page as undefined", () => {
      doc._userActivation = true;
      doc.print(true, undefined, 5);
      expect(mockSend).toHaveBeenCalledWith({ command: "print", start: 0, end: 5 });
    });

    it("should handle end page as undefined", () => {
      doc._userActivation = true;
      doc.print(true, 0, undefined);
      expect(mockSend).toHaveBeenCalledWith({ command: "print", start: 0, end: 0 });
    });
  });

  describe("parameter combinations", () => {
    it("should handle all boolean parameters set to true", () => {
      doc._userActivation = true;
      doc.print(true, 1, 5, true, true, true, true, true);
      expect(mockSend).toHaveBeenCalledWith({ command: "print", start: 1, end: 5 });
    });

    it("should handle all boolean parameters set to false", () => {
      doc._userActivation = true;
      doc.print(false, 1, 5, false, false, false, false, false);
      expect(mockSend).toHaveBeenCalledWith({ command: "print", start: 1, end: 5 });
    });

    it("should handle default values for all parameters", () => {
      doc._userActivation = true;
      doc.print();
      expect(mockSend).toHaveBeenCalledWith({ command: "print", start: 0, end: 0 });
    });

    it("should override object parameters with explicit later parameters", () => {
      doc._userActivation = true;
      const params = {
        bUI: false,
        nStart: 3,
        nEnd: 7,
      };
      // Even though params has nStart=3, explicit parameter nStart=2 should win
      // According to the code, when bUI is an object, it extracts params from it
      // So this test might need adjustment based on actual behavior
      doc.print(params, 2, 8);
      // The code shows that if bUI is an object, it extracts params from it
      // So nStart should be 3 from the object, not 2 from explicit parameter
      expect(mockSend).toHaveBeenCalledWith({ command: "print", start: 3, end: 7 });
    });
  });

  describe("real-world scenarios", () => {
    it("should handle printing range with printParams", () => {
      doc._userActivation = true;
      const printParams = new PrintParams({ lastPage: 20 });
      printParams.firstPage = 5;
      printParams.lastPage = 15;
      doc.print(true, 0, -1, false, false, false, false, true, printParams);
      expect(mockSend).toHaveBeenCalledWith({ command: "print", start: 5, end: 15 });
    });

    it("should handle printing entire document", () => {
      doc._userActivation = true;
      doc.print(true, 0, -1);
      expect(mockSend).toHaveBeenCalledWith({ command: "print", start: 0, end: 0 });
    });

    it("should handle printing single page", () => {
      doc._userActivation = true;
      doc.print(true, 5, 5);
      expect(mockSend).toHaveBeenCalledWith({ command: "print", start: 5, end: 5 });
    });

    it("should handle printing from page to end", () => {
      doc._userActivation = true;
      doc.print(true, 5, -1);
      expect(mockSend).toHaveBeenCalledWith({ command: "print", start: 5, end: 0 });
    });
  });
});

