import { PDFObjects } from "../../../src/display/pdf_objects.js";
import { describe, it, expect, beforeEach, jest } from "@jest/globals";

describe("PDFObjects delete method", () => {
  let pdfObjects;

  beforeEach(() => {
    pdfObjects = new PDFObjects();
  });

  describe("deleting non-existent objects", () => {
    it("should return false when trying to delete non-existent object", () => {
      const result = pdfObjects.delete("non-existent-id");
      expect(result).toBe(false);
    });

    it("should return false when trying to delete non-existent object with numeric ID", () => {
      const result = pdfObjects.delete("123");
      expect(result).toBe(false);
    });
  });

  describe("deleting unresolved objects", () => {
    it("should return false when trying to delete object with INITIAL_DATA", () => {
      // Create an object through the ensureObj method (which happens when we call get with callback)
      // This will create an object with INITIAL_DATA
      const callback = jest.fn();
      pdfObjects.get("initial-data-id", callback);

      // Try to delete - should fail because data is INITIAL_DATA
      const result = pdfObjects.delete("initial-data-id");
      expect(result).toBe(false);
    });
  });

  describe("deleting resolved objects", () => {
    it("should return true when deleting resolved object", () => {
      const objId = "resolved-id";
      const testData = { foo: "bar" };

      pdfObjects.resolve(objId, testData);

      const result = pdfObjects.delete(objId);
      expect(result).toBe(true);
    });

    it("should actually remove the object from internal storage", () => {
      const objId = "test-id";
      const testData = { test: "data" };

      pdfObjects.resolve(objId, testData);

      // Verify object exists before deletion
      expect(pdfObjects.has(objId)).toBe(true);

      // Delete the object
      const deleteResult = pdfObjects.delete(objId);
      expect(deleteResult).toBe(true);

      // Verify object no longer exists
      expect(pdfObjects.has(objId)).toBe(false);
    });

    it("should allow re-adding object after deletion", () => {
      const objId = "reusable-id";
      const firstData = { first: "data" };
      const secondData = { second: "data" };

      // Add and delete first object
      pdfObjects.resolve(objId, firstData);
      expect(pdfObjects.delete(objId)).toBe(true);

      // Add new object with same ID
      pdfObjects.resolve(objId, secondData);

      // Should be able to retrieve the new data
      const retrievedData = pdfObjects.get(objId);
      expect(retrievedData).toEqual(secondData);
    });

    it("should handle multiple deletions and additions", () => {
      const objId = "multi-id";

      // First cycle
      pdfObjects.resolve(objId, "data1");
      expect(pdfObjects.delete(objId)).toBe(true);

      // Second cycle
      pdfObjects.resolve(objId, "data2");
      expect(pdfObjects.delete(objId)).toBe(true);

      // Third cycle
      pdfObjects.resolve(objId, "data3");
      expect(pdfObjects.delete(objId)).toBe(true);

      // Final state should not have the object
      expect(pdfObjects.has(objId)).toBe(false);
    });
  });

  describe("edge cases", () => {
    it("should handle deletion of object with null data", () => {
      const objId = "null-data-id";

      pdfObjects.resolve(objId, null);

      const result = pdfObjects.delete(objId);
      expect(result).toBe(true);
    });

    it("should handle deletion of object with undefined data", () => {
      const objId = "undefined-data-id";

      pdfObjects.resolve(objId, undefined);

      const result = pdfObjects.delete(objId);
      expect(result).toBe(true);
    });

    it("should handle deletion of object with complex data", () => {
      const objId = "complex-data-id";
      const complexData = {
        nested: {
          array: [1, 2, 3],
          func: () => "test"
        }
      };

      pdfObjects.resolve(objId, complexData);

      const result = pdfObjects.delete(objId);
      expect(result).toBe(true);
    });

    it("should not affect other objects when deleting one", () => {
      const objId1 = "obj1";
      const objId2 = "obj2";
      const data1 = { id: 1 };
      const data2 = { id: 2 };

      pdfObjects.resolve(objId1, data1);
      pdfObjects.resolve(objId2, data2);

      // Delete first object
      expect(pdfObjects.delete(objId1)).toBe(true);

      // Second object should still exist
      expect(pdfObjects.has(objId2)).toBe(true);
      expect(pdfObjects.get(objId2)).toEqual(data2);
    });
  });

  describe("interaction with other methods", () => {
    it("should make get() throw after deletion", () => {
      const objId = "to-delete";
      const data = { value: 42 };

      pdfObjects.resolve(objId, data);

      // Should be able to get before deletion
      expect(pdfObjects.get(objId)).toEqual(data);

      // Delete the object
      expect(pdfObjects.delete(objId)).toBe(true);

      // Should throw when trying to get deleted object
      expect(() => pdfObjects.get(objId)).toThrow(`Requesting object that isn't resolved yet ${objId}.`);
    });

    it("should work with iterator after deletion", () => {
      const objId1 = "keep";
      const objId2 = "delete";

      pdfObjects.resolve(objId1, "keep-data");
      pdfObjects.resolve(objId2, "delete-data");

      // Delete second object
      pdfObjects.delete(objId2);

      // Iterator should only include remaining object
      const iterator = pdfObjects[Symbol.iterator]();
      const items = Array.from(iterator);

      expect(items).toHaveLength(1);
      expect(items[0][0]).toBe(objId1);
      expect(items[0][1]).toBe("keep-data");
    });

    it("should work with clear() after deletion", () => {
      const objId = "test-clear";

      pdfObjects.resolve(objId, "data");
      pdfObjects.delete(objId);

      // Clear should not throw even though object was deleted
      expect(() => pdfObjects.clear()).not.toThrow();
    });
  });
});

