import { PDFObjects } from "../../../src/display/pdf_objects.js";
import { describe, it, expect, beforeEach, jest } from "@jest/globals";

describe("PDFObjects resolve method", () => {
  let pdfObjects;

  beforeEach(() => {
    pdfObjects = new PDFObjects();
  });

  describe("basic resolution", () => {
    it("should resolve an object with data", () => {
      const objId = "test-id";
      const testData = { foo: "bar" };

      pdfObjects.resolve(objId, testData);

      // Should be able to get the resolved data
      const retrievedData = pdfObjects.get(objId);
      expect(retrievedData).toEqual(testData);
    });

    it("should resolve an object with null data", () => {
      const objId = "null-id";

      pdfObjects.resolve(objId, null);

      const retrievedData = pdfObjects.get(objId);
      expect(retrievedData).toBeNull();
    });

    it("should resolve an object with undefined data (becomes null due to default parameter)", () => {
      const objId = "undefined-id";

      pdfObjects.resolve(objId, undefined);

      const retrievedData = pdfObjects.get(objId);
      // Note: resolve(objId, data = null) means undefined becomes null
      expect(retrievedData).toBeNull();
    });

    it("should resolve an object with default null data when not provided", () => {
      const objId = "default-null-id";

      pdfObjects.resolve(objId); // No data argument

      const retrievedData = pdfObjects.get(objId);
      expect(retrievedData).toBeNull();
    });
  });

  describe("multiple resolutions", () => {
    it("should be able to resolve multiple objects", () => {
      const objId1 = "obj1";
      const objId2 = "obj2";
      const data1 = { id: 1 };
      const data2 = { id: 2 };

      pdfObjects.resolve(objId1, data1);
      pdfObjects.resolve(objId2, data2);

      expect(pdfObjects.get(objId1)).toEqual(data1);
      expect(pdfObjects.get(objId2)).toEqual(data2);
    });

    it("should overwrite data when resolving same object multiple times", () => {
      const objId = "overwrite-id";
      const firstData = "first";
      const secondData = "second";

      pdfObjects.resolve(objId, firstData);
      expect(pdfObjects.get(objId)).toBe(firstData);

      pdfObjects.resolve(objId, secondData);
      expect(pdfObjects.get(objId)).toBe(secondData);
    });
  });

  describe("async behavior", () => {
    it("should call callback immediately if object already resolved", async () => {
      const objId = "async-resolved-id";
      const testData = { async: "data" };
      const callback = jest.fn();

      // Resolve first
      pdfObjects.resolve(objId, testData);

      // Then get with callback
      pdfObjects.get(objId, callback);

      // Callback should be called asynchronously
      await new Promise(resolve => setTimeout(resolve, 0));
      expect(callback).toHaveBeenCalledWith(testData);
    });

    it("should call callback when object gets resolved later", async () => {
      const objId = "async-later-id";
      const testData = { later: "data" };
      const callback = jest.fn();

      // Get with callback first (object not resolved yet)
      pdfObjects.get(objId, callback);

      // Resolve later
      pdfObjects.resolve(objId, testData);

      // Callback should be called asynchronously after resolution
      await new Promise(resolve => setTimeout(resolve, 0));
      expect(callback).toHaveBeenCalledWith(testData);
    });

    it("should handle multiple callbacks for same object", async () => {
      const objId = "multiple-callbacks-id";
      const testData = "test";
      const callback1 = jest.fn();
      const callback2 = jest.fn();
      const callback3 = jest.fn();

      // Add multiple callbacks before resolution
      pdfObjects.get(objId, callback1);
      pdfObjects.get(objId, callback2);

      // Resolve
      pdfObjects.resolve(objId, testData);

      // Add another callback after resolution
      pdfObjects.get(objId, callback3);

      // All callbacks should be called
      await new Promise(resolve => setTimeout(resolve, 0));
      expect(callback1).toHaveBeenCalledWith(testData);
      expect(callback2).toHaveBeenCalledWith(testData);
      expect(callback3).toHaveBeenCalledWith(testData);
    });
  });

  describe("interaction with other methods", () => {
    it("should make object available through has() after resolution", () => {
      const objId = "has-test-id";

      expect(pdfObjects.has(objId)).toBe(false);

      pdfObjects.resolve(objId, "data");

      expect(pdfObjects.has(objId)).toBe(true);
    });

    it("should include resolved object in iterator", () => {
      const objId1 = "iterator-id-1";
      const objId2 = "iterator-id-2";
      const data1 = "data1";
      const data2 = "data2";

      pdfObjects.resolve(objId1, data1);
      pdfObjects.resolve(objId2, data2);

      const iterator = pdfObjects[Symbol.iterator]();
      const items = Array.from(iterator);

      expect(items).toHaveLength(2);
      expect(items.map(([id]) => id)).toEqual(expect.arrayContaining([objId1, objId2]));
      expect(items.map(([, data]) => data)).toEqual(expect.arrayContaining([data1, data2]));
    });

    it("should not include unresolved objects in iterator", () => {
      const objId = "unresolved-iterator-id";

      // Create object but don't resolve it
      const callback = jest.fn();
      pdfObjects.get(objId, callback);

      const iterator = pdfObjects[Symbol.iterator]();
      const items = Array.from(iterator);

      expect(items).toHaveLength(0);
    });

    it("should allow deletion after resolution", () => {
      const objId = "delete-after-resolve";
      const testData = { deletable: true };

      pdfObjects.resolve(objId, testData);

      expect(pdfObjects.delete(objId)).toBe(true);
      expect(pdfObjects.has(objId)).toBe(false);
    });
  });

  describe("edge cases", () => {
    it("should resolve object with complex data structure", () => {
      const objId = "complex-data-id";
      const complexData = {
        nested: {
          array: [1, 2, 3],
          func: () => "test",
          date: new Date(),
          regex: /test/i
        }
      };

      pdfObjects.resolve(objId, complexData);

      const retrievedData = pdfObjects.get(objId);
      expect(retrievedData).toEqual(complexData);
      expect(retrievedData.nested.func()).toBe("test");
      expect(retrievedData.nested.regex.test("TEST")).toBe(true);
    });

    it("should resolve object with falsy values", () => {
      const falsyValues = [false, 0, "", NaN];

      falsyValues.forEach((value, index) => {
        const objId = `falsy-${index}`;
        pdfObjects.resolve(objId, value);

        if (Number.isNaN(value)) {
          expect(pdfObjects.get(objId)).toBeNaN();
        } else {
          expect(pdfObjects.get(objId)).toBe(value);
        }
      });
    });

    it("should handle very long object IDs", () => {
      const longId = "a".repeat(1000);
      const data = "test data";

      pdfObjects.resolve(longId, data);

      expect(pdfObjects.get(longId)).toBe(data);
    });

    it("should handle special characters in object IDs", () => {
      const specialChars = ["id-with-dash", "id.with.dots", "id:with:colons", "id with spaces"];

      specialChars.forEach(id => {
        const testData = `data for ${id}`;
        pdfObjects.resolve(id, testData);

        expect(pdfObjects.get(id)).toBe(testData);
      });
    });
  });

  describe("error handling", () => {
    it("should throw when getting unresolved object without callback", () => {
      const objId = "unresolved-id";

      // Object exists but not resolved
      const callback = jest.fn();
      pdfObjects.get(objId, callback);

      expect(() => pdfObjects.get(objId)).toThrow(
        `Requesting object that isn't resolved yet ${objId}.`
      );
    });

    it("should not throw when getting with callback for unresolved object", () => {
      const objId = "callback-unresolved-id";
      const callback = jest.fn();

      expect(() => pdfObjects.get(objId, callback)).not.toThrow();
    });
  });
});

