  Promise.withResolvers = function() {
    let resolve, reject;
    const promise = new Promise((res, rej) => {
      resolve = res;
      reject = rej;
    });
    return { promise, resolve, reject };
  };
}

import { PDFObjects } from "../../../src/display/pdf_objects.js";
import { describe, it, expect, beforeEach, jest } from "@jest/globals";

describe("PDFObjects clear method", () => {
  let pdfObjects;

  beforeEach(() => {
    pdfObjects = new PDFObjects();
  });

  describe("clearing empty objects", () => {
    it("should not throw when clearing empty PDFObjects", () => {
      expect(() => pdfObjects.clear()).not.toThrow();
    });

    it("should remain empty after clearing empty PDFObjects", () => {
      pdfObjects.clear();

      // Verify no objects exist
      const iterator = pdfObjects[Symbol.iterator]();
      const items = Array.from(iterator);
      expect(items).toHaveLength(0);
    });
  });

  describe("clearing objects without bitmap data", () => {
    it("should clear objects with regular data", () => {
      const objId1 = "obj1";
      const objId2 = "obj2";
      const data1 = { foo: "bar" };
      const data2 = "string data";

      pdfObjects.resolve(objId1, data1);
      pdfObjects.resolve(objId2, data2);

      // Verify objects exist before clearing
      expect(pdfObjects.has(objId1)).toBe(true);
      expect(pdfObjects.has(objId2)).toBe(true);

      // Clear all objects
      pdfObjects.clear();

      // Verify objects no longer exist
      expect(pdfObjects.has(objId1)).toBe(false);
      expect(pdfObjects.has(objId2)).toBe(false);
    });

    it("should clear objects with null data", () => {
      const objId = "null-obj";

      pdfObjects.resolve(objId, null);
      expect(pdfObjects.has(objId)).toBe(true);

      pdfObjects.clear();
      expect(pdfObjects.has(objId)).toBe(false);
    });

    it("should clear objects with undefined data", () => {
      const objId = "undefined-obj";

      pdfObjects.resolve(objId, undefined);
      expect(pdfObjects.has(objId)).toBe(true);

      pdfObjects.clear();
      expect(pdfObjects.has(objId)).toBe(false);
    });

    it("should clear objects with complex data structures", () => {
      const objId = "complex-obj";
      const complexData = {
        nested: {
          array: [1, 2, 3],
          func: () => "test",
          date: new Date(),
          regex: /test/i
        }
      };

      pdfObjects.resolve(objId, complexData);
      expect(pdfObjects.has(objId)).toBe(true);

      pdfObjects.clear();
      expect(pdfObjects.has(objId)).toBe(false);
    });
  });

  describe("clearing objects with bitmap data", () => {
    it("should call close() on bitmap data when clearing", () => {
      const objId = "bitmap-obj";
      const mockClose = jest.fn();
      const bitmapData = {
        bitmap: {
          close: mockClose
        },
        width: 100,
        height: 100
      };

      pdfObjects.resolve(objId, bitmapData);

      // Clear should call close() on the bitmap
      pdfObjects.clear();

      expect(mockClose).toHaveBeenCalledTimes(1);
      expect(pdfObjects.has(objId)).toBe(false);
    });

    it("should handle bitmap data with null close method", () => {
      const objId = "null-close-obj";
      const bitmapData = {
        bitmap: {
          close: null
        }
      };

      pdfObjects.resolve(objId, bitmapData);

      // The current implementation will throw when trying to call null as a function
      // This tests the actual behavior of the code
      expect(() => pdfObjects.clear()).toThrow(TypeError);

      // Since clear() throws, the object should not be cleared
      // Verify the object still exists
      expect(pdfObjects.has(objId)).toBe(true);
    });

    it("should handle bitmap data without close method", () => {
      const objId = "no-close-obj";
      const bitmapData = {
        bitmap: {} // No close method
      };

      pdfObjects.resolve(objId, bitmapData);

      // The current implementation will throw when trying to call undefined as a function
      expect(() => pdfObjects.clear()).toThrow(TypeError);

      // Since clear() throws, the object should not be cleared
      expect(pdfObjects.has(objId)).toBe(true);
    });

    it("should handle data with null bitmap", () => {
      const objId = "null-bitmap-obj";
      const data = {
        bitmap: null,
        otherProp: "value"
      };

      pdfObjects.resolve(objId, data);

      expect(() => pdfObjects.clear()).not.toThrow();
      expect(pdfObjects.has(objId)).toBe(false);
    });

    it("should handle data with undefined bitmap", () => {
      const objId = "undefined-bitmap-obj";
      const data = {
        bitmap: undefined,
        otherProp: "value"
      };

      pdfObjects.resolve(objId, data);

      expect(() => pdfObjects.clear()).not.toThrow();
      expect(pdfObjects.has(objId)).toBe(false);
    });
  });

  describe("clearing mixed objects (with and without bitmap)", () => {
    it("should clear all objects and call close() only on bitmap objects", () => {
      const objId1 = "regular-obj";
      const objId2 = "bitmap-obj";
      const objId3 = "another-regular";

      const mockClose = jest.fn();
      const regularData = { type: "regular" };
      const bitmapData = {
        bitmap: { close: mockClose },
        type: "bitmap"
      };
      const anotherRegularData = { type: "another" };

      pdfObjects.resolve(objId1, regularData);
      pdfObjects.resolve(objId2, bitmapData);
      pdfObjects.resolve(objId3, anotherRegularData);

      // Verify all objects exist
      expect(pdfObjects.has(objId1)).toBe(true);
      expect(pdfObjects.has(objId2)).toBe(true);
      expect(pdfObjects.has(objId3)).toBe(true);

      // Clear all objects
      pdfObjects.clear();

      // close() should only be called once (for the bitmap object)
      expect(mockClose).toHaveBeenCalledTimes(1);

      // All objects should be removed
      expect(pdfObjects.has(objId1)).toBe(false);
      expect(pdfObjects.has(objId2)).toBe(false);
      expect(pdfObjects.has(objId3)).toBe(false);
    });

    it("should handle multiple bitmap objects", () => {
      const objId1 = "bitmap1";
      const objId2 = "bitmap2";

      const mockClose1 = jest.fn();
      const mockClose2 = jest.fn();
      const bitmapData1 = { bitmap: { close: mockClose1 } };
      const bitmapData2 = { bitmap: { close: mockClose2 } };

      pdfObjects.resolve(objId1, bitmapData1);
      pdfObjects.resolve(objId2, bitmapData2);

      pdfObjects.clear();

      // Both close methods should be called
      expect(mockClose1).toHaveBeenCalledTimes(1);
      expect(mockClose2).toHaveBeenCalledTimes(1);

      expect(pdfObjects.has(objId1)).toBe(false);
      expect(pdfObjects.has(objId2)).toBe(false);
    });
  });

  describe("iterator after clearing", () => {
    it("should return empty iterator after clearing", () => {
      const objId1 = "obj1";
      const objId2 = "obj2";

      pdfObjects.resolve(objId1, "data1");
      pdfObjects.resolve(objId2, "data2");

      // Verify iterator has items before clearing
      const iteratorBefore = pdfObjects[Symbol.iterator]();
      const itemsBefore = Array.from(iteratorBefore);
      expect(itemsBefore).toHaveLength(2);

      // Clear objects
      pdfObjects.clear();

      // Verify iterator is empty after clearing
      const iteratorAfter = pdfObjects[Symbol.iterator]();
      const itemsAfter = Array.from(iteratorAfter);
      expect(itemsAfter).toHaveLength(0);
    });

    it("should not include unresolved objects after clearing", () => {
      const objId = "unresolved-obj";

      // Create unresolved object (by calling get with callback)
      const callback = jest.fn();
      pdfObjects.get(objId, callback);

      // Clear should handle unresolved objects
      expect(() => pdfObjects.clear()).not.toThrow();

      // Iterator should be empty
      const iterator = pdfObjects[Symbol.iterator]();
      const items = Array.from(iterator);
      expect(items).toHaveLength(0);
    });
  });

  describe("interaction with other methods after clearing", () => {
    it("should allow adding new objects after clearing", () => {
      const objId = "new-obj";
      const initialData = "initial";
      const newData = "new";

      // Add, clear, then add again
      pdfObjects.resolve(objId, initialData);
      expect(pdfObjects.get(objId)).toBe(initialData);

      pdfObjects.clear();
      expect(() => pdfObjects.get(objId)).toThrow();

      // Add new object with same ID
      pdfObjects.resolve(objId, newData);
      expect(pdfObjects.get(objId)).toBe(newData);
    });

    it("should make get() throw for cleared objects", () => {
      const objId = "cleared-obj";
      const data = { value: 42 };

      pdfObjects.resolve(objId, data);
      expect(pdfObjects.get(objId)).toEqual(data);

      pdfObjects.clear();

      // Should throw when trying to get cleared object
      expect(() => pdfObjects.get(objId)).toThrow(
        `Requesting object that isn't resolved yet ${objId}.`
      );
    });

    it("should return false for has() after clearing", () => {
      const objId = "has-test-obj";

      pdfObjects.resolve(objId, "data");
      expect(pdfObjects.has(objId)).toBe(true);

      pdfObjects.clear();
      expect(pdfObjects.has(objId)).toBe(false);
    });

    it("should return false for delete() after clearing", () => {
      const objId = "delete-test-obj";

      pdfObjects.resolve(objId, "data");

      // Clear first
      pdfObjects.clear();

      // Try to delete cleared object
      const result = pdfObjects.delete(objId);
      expect(result).toBe(false);
    });

    it("should handle get() with callback for cleared objects", async () => {
      const objId = "callback-cleared-obj";
      const callback = jest.fn();

      pdfObjects.resolve(objId, "data");

      // Clear before setting up callback
      pdfObjects.clear();

      // Get with callback on cleared object
      pdfObjects.get(objId, callback);

      // Callback should not be called since object was cleared
      await new Promise(resolve => setTimeout(resolve, 10));
      expect(callback).not.toHaveBeenCalled();
    });
  });

  describe("edge cases", () => {
    it("should handle objects with symbol as ID", () => {
      const symbolId = Symbol("test");
      const stringId = "test";

      // PDFObjects uses string keys, so symbol won't work with resolve/get
      // But clear should still work without errors
      expect(() => pdfObjects.clear()).not.toThrow();
    });

    it("should handle large number of objects", () => {
      // Add many objects
      for (let i = 0; i < 100; i++) {
        pdfObjects.resolve(`obj-${i}`, `data-${i}`);
      }

      // All objects should exist
      for (let i = 0; i < 100; i++) {
        expect(pdfObjects.has(`obj-${i}`)).toBe(true);
      }

      // Clear all objects
      pdfObjects.clear();

      // No objects should exist
      for (let i = 0; i < 100; i++) {
        expect(pdfObjects.has(`obj-${i}`)).toBe(false);
      }

      // Iterator should be empty
      const iterator = pdfObjects[Symbol.iterator]();
      const items = Array.from(iterator);
      expect(items).toHaveLength(0);
    });

    it("should handle clear() called multiple times", () => {
      const objId = "multi-clear-obj";

      pdfObjects.resolve(objId, "data");

      // First clear
      pdfObjects.clear();
      expect(pdfObjects.has(objId)).toBe(false);

      // Second clear should not throw
      expect(() => pdfObjects.clear()).not.toThrow();

      // Third clear should not throw
      expect(() => pdfObjects.clear()).not.toThrow();
    });

    it("should work with objects that have been deleted", () => {
      const objId1 = "keep";
      const objId2 = "delete";

      pdfObjects.resolve(objId1, "keep-data");
      pdfObjects.resolve(objId2, "delete-data");

      // Delete one object
      pdfObjects.delete(objId2);

      // Clear should work without errors
      expect(() => pdfObjects.clear()).not.toThrow();

      // Remaining object should be cleared
      expect(pdfObjects.has(objId1)).toBe(false);
    });
  });

  describe("performance and memory", () => {
    it("should not keep references to old objects after clearing", () => {
      const objId = "memory-test";
      let largeData = new Array(10000).fill("test data");

      pdfObjects.resolve(objId, largeData);

      // Clear should release references
      pdfObjects.clear();

      // Allow garbage collection
      largeData = null;

      // Try to add new object with same ID
      pdfObjects.resolve(objId, "new data");
      expect(pdfObjects.get(objId)).toBe("new data");
    });
  });
});

