import { HighlightOutliner } from "../../../../../src/display/editor/drawers/highlight.js";
import { describe, it, expect, beforeEach } from "@jest/globals";

describe("HighlightOutline.serialize", () => {
  let highlightOutline;

  beforeEach(() => {
    // Create a simple rectangle box to get a HighlightOutline instance
    const boxes = [{ x: 0, y: 0, width: 100, height: 100 }];
    const outliner = new HighlightOutliner(boxes, 0, 0, true);
    highlightOutline = outliner.getOutlines();
  });

  it("should serialize with identity transformation when bbox matches original", () => {
    // When we serialize with the same box that was used to create the outline
    // (adjusting for the fact that box has [minX, minY, width, height] format)
    const box = highlightOutline.box;
    const blX = box[0];
    const blY = box[1];
    const trX = box[0] + box[2];
    const trY = box[1] + box[3];

    const result = highlightOutline.serialize([blX, blY, trX, trY], 0);

    expect(Array.isArray(result)).toBe(true);
    expect(result.length).toBe(1); // Single outline for a single rectangle

    // The outline should be a closed polygon around the rectangle
    const outline = result[0];
    expect(outline.length).toBe(8); // 4 points * 2 coordinates

    // Check it's a rectangle: (0,0) -> (0,100) -> (100,100) -> (100,0)
    // Note: there might be floating point rounding errors
    expect(outline[0]).toBeCloseTo(blX, 4); // x1
    expect(outline[1]).toBeCloseTo(blY, 4); // y1

    expect(outline[2]).toBeCloseTo(blX, 4); // x2
    expect(outline[3]).toBeCloseTo(trY, 4); // y2

    expect(outline[4]).toBeCloseTo(trX, 4); // x3
    expect(outline[5]).toBeCloseTo(trY, 4); // y3

    expect(outline[6]).toBeCloseTo(trX, 4); // x4
    expect(outline[7]).toBeCloseTo(blY, 4); // y4
  });

  it("should scale and translate outlines correctly", () => {
    // Test with a different bounding box
    const bbox = [50, 60, 150, 160]; // 100x100 box moved by (50,60)
    const result = highlightOutline.serialize(bbox, 0);

    const outline = result[0];

    // Original outline is 100x100 at (0,0)
    // After serializing to bbox [50,60,150,160], it should be at (50,60)
    expect(outline[0]).toBeCloseTo(50, 4); // x1
    expect(outline[1]).toBeCloseTo(60, 4); // y1

    expect(outline[2]).toBeCloseTo(50, 4); // x2
    expect(outline[3]).toBeCloseTo(160, 4); // y2

    expect(outline[4]).toBeCloseTo(150, 4); // x3
    expect(outline[5]).toBeCloseTo(160, 4); // y3

    expect(outline[6]).toBeCloseTo(150, 4); // x4
    expect(outline[7]).toBeCloseTo(60, 4); // y4
  });

  it("should scale outlines to different sizes", () => {
    // Test scaling to a larger box
    const bbox = [0, 0, 200, 300]; // 200x300 box
    const result = highlightOutline.serialize(bbox, 0);

    const outline = result[0];

    // Original 100x100 outline scaled to 200x300
    expect(outline[0]).toBeCloseTo(0, 4); // x1
    expect(outline[1]).toBeCloseTo(0, 4); // y1

    expect(outline[2]).toBeCloseTo(0, 4); // x2  
    expect(outline[3]).toBeCloseTo(300, 4); // y2 (scaled height)

    expect(outline[4]).toBeCloseTo(200, 4); // x3 (scaled width)
    expect(outline[5]).toBeCloseTo(300, 4); // y3

    expect(outline[6]).toBeCloseTo(200, 4); // x4
    expect(outline[7]).toBeCloseTo(0, 4); // y4
  });

  it("should ignore rotation parameter", () => {
    const bbox = [0, 0, 100, 100];

    const result1 = highlightOutline.serialize(bbox, 0);
    const result2 = highlightOutline.serialize(bbox, 90);
    const result3 = highlightOutline.serialize(bbox, 180);
    const result4 = highlightOutline.serialize(bbox, 270);

    // All results should be identical since rotation is ignored
    expect(result1).toEqual(result2);
    expect(result1).toEqual(result3);
    expect(result1).toEqual(result4);
  });

  it("should return new array instances each call", () => {
    const bbox = [0, 0, 100, 100];

    const result1 = highlightOutline.serialize(bbox, 0);
    const result2 = highlightOutline.serialize(bbox, 0);

    // Should return new arrays each time
    expect(result1).not.toBe(result2);
    expect(result1[0]).not.toBe(result2[0]);
  });

  it("should handle negative coordinates", () => {
    const bbox = [-100, -50, 0, 50]; // 100x100 box at (-100,-50)
    const result = highlightOutline.serialize(bbox, 0);

    const outline = result[0];

    expect(outline[0]).toBeCloseTo(-100, 4); // x1
    expect(outline[1]).toBeCloseTo(-50, 4); // y1

    expect(outline[2]).toBeCloseTo(-100, 4); // x2
    expect(outline[3]).toBeCloseTo(50, 4); // y2

    expect(outline[4]).toBeCloseTo(0, 4); // x3
    expect(outline[5]).toBeCloseTo(50, 4); // y3

    expect(outline[6]).toBeCloseTo(0, 4); // x4
    expect(outline[7]).toBeCloseTo(-50, 4); // y4
  });

  it("should work with multiple boxes creating complex outlines", () => {
    // Create two overlapping boxes
    const boxes = [
      { x: 0, y: 0, width: 100, height: 100 },
      { x: 50, y: 50, width: 100, height: 100 }
    ];
    const outliner = new HighlightOutliner(boxes, 0, 0, true);
    const complexOutline = outliner.getOutlines();

    const bbox = [0, 0, 200, 200];
    const result = complexOutline.serialize(bbox, 0);

    expect(Array.isArray(result)).toBe(true);
    // Should have at least one outline
    expect(result.length).toBeGreaterThan(0);

    // Each outline should have an even number of coordinates
    for (const outline of result) {
      expect(outline.length % 2).toBe(0);
    }
  });

  it("should preserve box, firstPoint, and lastPoint properties", () => {
    // Verify properties are accessible
    expect(highlightOutline.box).toBeInstanceOf(Float32Array);
    expect(highlightOutline.box.length).toBe(4);

    expect(Array.isArray(highlightOutline.firstPoint)).toBe(true);
    expect(highlightOutline.firstPoint.length).toBe(2);

    expect(Array.isArray(highlightOutline.lastPoint)).toBe(true);
    expect(highlightOutline.lastPoint.length).toBe(2);
  });
});

