import { beforeEach, describe, expect, it } from "@jest/globals";
import { FreeHighlightOutliner } from "../../../../../src/display/editor/drawers/highlight.js";

describe("FreeHighlightOutline.newOutliner", () => {
  let freeHighlightOutline;
  let mockOutline;
  let mockPoints;
  let mockBox;

  beforeEach(() => {
    // Create a valid outline for FreeDrawOutline constructor
    // The outline format is: [x0, y0, x1, y1, x2, y2, ...] in groups of 6
    // Starting point is at indices 4-5
    // If first element of a group is NaN, it's a straight line
    // Otherwise, it's a bezier curve with control points at 0/1, 2/3

    // Create a simple outline with just a starting point (indices 4-5)
    // and one straight line segment (indices 6-11, with NaN at index 6)
    mockOutline = new Float32Array(12);
    // Starting point at indices 4-5
    mockOutline[4] = 10;
    mockOutline[5] = 10;
    // Straight line segment: NaN at index 6 indicates straight line
    mockOutline[6] = NaN;
    mockOutline[7] = 0; // Unused for straight line
    mockOutline[8] = 0; // Unused for straight line
    mockOutline[9] = 0; // Unused for straight line
    mockOutline[10] = 50; // Endpoint x
    mockOutline[11] = 50; // Endpoint y

    mockPoints = [10, 10, 50, 50]; // Simple points array
    mockBox = [0, 0, 100, 100]; // [x, y, width, height]
    const scaleFactor = 1.0;
    const innerMargin = 5;
    const isLTR = true;

    // Create a FreeHighlightOutliner
    const point = { x: 10, y: 20 };
    const thickness = 2;
    const outliner = new FreeHighlightOutliner(
      point,
      mockBox,
      scaleFactor,
      thickness,
      isLTR,
      innerMargin
    );

    // Create a FreeHighlightOutline using newFreeDrawOutline method
    freeHighlightOutline = outliner.newFreeDrawOutline(
      mockOutline,
      mockPoints,
      mockBox,
      scaleFactor,
      innerMargin,
      isLTR
    );
  });

  it("should create a FreeHighlightOutliner instance with correct parameters", () => {
    const point = { x: 10, y: 20 };
    const box = [0, 0, 200, 200];
    const testScaleFactor = 2.0;
    const thickness = 3;
    const testIsLTR = false;
    const testInnerMargin = 10;

    const outliner = freeHighlightOutline.newOutliner(
      point,
      box,
      testScaleFactor,
      thickness,
      testIsLTR,
      testInnerMargin
    );

    // Check that we get a FreeHighlightOutliner instance
    expect(outliner).toBeDefined();
    expect(outliner.constructor.name).toBe("FreeHighlightOutliner");

    // Verify it has the expected methods from FreeDrawOutliner
    expect(typeof outliner.isEmpty).toBe("function");
    expect(typeof outliner.add).toBe("function");
  });

  it("should use default innerMargin when not provided", () => {
    const point = { x: 10, y: 20 };
    const box = [0, 0, 100, 100];
    const testScaleFactor = 1.0;
    const thickness = 2;
    const testIsLTR = true;

    const outliner = freeHighlightOutline.newOutliner(
      point,
      box,
      testScaleFactor,
      thickness,
      testIsLTR
    );

    expect(outliner).toBeDefined();
    expect(outliner.constructor.name).toBe("FreeHighlightOutliner");
  });

  it("should create outliner with LTR direction", () => {
    const point = { x: 10, y: 20 };
    const box = [0, 0, 100, 100];
    const testScaleFactor = 1.0;
    const thickness = 2;
