  });

  it("should handle different scale factors correctly", () => {
    const point = { x: 10, y: 20 };
    const box = [0, 0, 100, 100];
    const thickness = 2;
    const testIsLTR = true;

    // Test with scaleFactor = 0.5
    const outliner1 = freeHighlightOutline.newOutliner(
      point,
      box,
      0.5,
      thickness,
      testIsLTR
    );
    expect(outliner1).toBeDefined();

    // Test with scaleFactor = 2.0
    const outliner2 = freeHighlightOutline.newOutliner(
      point,
      box,
      2.0,
      thickness,
      testIsLTR
    );
    expect(outliner2).toBeDefined();

    // Test with scaleFactor = 0 (edge case)
    const outliner3 = freeHighlightOutline.newOutliner(
