import { beforeEach, describe, expect, it } from "@jest/globals";
import { FreeHighlightOutliner } from "../../../../../src/display/editor/drawers/highlight.js";

describe("FreeHighlightOutliner.newFreeDrawOutline", () => {
  let freeHighlightOutliner;
  let mockOutline;
  let mockPoints;
  let mockBox;
  let scaleFactor;
  let innerMargin;
  let isLTR;

  beforeEach(() => {
    // Create mock outliner with a point
    const point = { x: 10, y: 20 };
    mockBox = [0, 0, 100, 100];
    scaleFactor = 1.0;
    const thickness = 2;
    isLTR = true;
    innerMargin = 5;

    freeHighlightOutliner = new FreeHighlightOutliner(
      point,
      mockBox,
      scaleFactor,
      thickness,
      isLTR,
      innerMargin
    );

    // Create a valid outline for FreeDrawOutline constructor
    // The outline format is: [x0, y0, x1, y1, x2, y2, ...] in groups of 6
    // Starting point is at indices 4-5
    // If first element of a group is NaN, it's a straight line
    // Otherwise, it's a bezier curve with control points at 0/1, 2/3
    mockOutline = new Float32Array(12);
    // Starting point at indices 4-5
    mockOutline[4] = 10;
    mockOutline[5] = 10;
    // Straight line segment: NaN at index 6 indicates straight line
    mockOutline[6] = NaN;
    mockOutline[7] = 0; // Unused for straight line
    mockOutline[8] = 0; // Unused for straight line
    mockOutline[9] = 0; // Unused for straight line
    mockOutline[10] = 50; // Endpoint x
    mockOutline[11] = 50; // Endpoint y

    mockPoints = [10, 10, 50, 50]; // Simple points array
  });

  it("should create a FreeHighlightOutline instance", () => {
    const result = freeHighlightOutliner.newFreeDrawOutline(
      mockOutline,
      mockPoints,
      mockBox,
      scaleFactor,
      innerMargin,
      isLTR
    );

    expect(result).toBeDefined();
    expect(result.constructor.name).toBe("FreeHighlightOutline");
  });

  it("should pass correct parameters to FreeHighlightOutline constructor", () => {
    const result = freeHighlightOutliner.newFreeDrawOutline(
      mockOutline,
      mockPoints,
      mockBox,
      scaleFactor,
      innerMargin,
      isLTR
    );

    // Verify the FreeHighlightOutline has expected properties
    expect(result.box).toBeDefined();
    expect(result.firstPoint).toBeDefined();
    expect(result.lastPoint).toBeDefined();

    // The outline should have been normalized (coordinates between 0-1)
    // Since mockOutline has points [10,10] and [50,50] in a 100x100 box
    // Normalized values should be approximately 0.1 and 0.5
    // But we can't directly access private fields
  });

  it("should handle different scale factors", () => {
    const testScaleFactor = 2.0;

    const result = freeHighlightOutliner.newFreeDrawOutline(
      mockOutline,
      mockPoints,
      mockBox,
      testScaleFactor,
      innerMargin,
      isLTR
    );

    expect(result).toBeDefined();
    expect(result.constructor.name).toBe("FreeHighlightOutline");
  });

  it("should handle different inner margin values", () => {
    const testInnerMargin = 10;

    const result = freeHighlightOutliner.newFreeDrawOutline(
      mockOutline,
      mockPoints,
      mockBox,
      scaleFactor,
      testInnerMargin,
      isLTR
    );

    expect(result).toBeDefined();
    expect(result.constructor.name).toBe("FreeHighlightOutline");
  });

  it("should handle LTR vs RTL direction", () => {
    // Test LTR
    const resultLTR = freeHighlightOutliner.newFreeDrawOutline(
      mockOutline,
      mockPoints,
      mockBox,
      scaleFactor,
      innerMargin,
      true
    );

    expect(resultLTR).toBeDefined();
    expect(resultLTR.constructor.name).toBe("FreeHighlightOutline");

    // Test RTL  
    const resultRTL = freeHighlightOutliner.newFreeDrawOutline(
      mockOutline,
      mockPoints,
      mockBox,
      scaleFactor,
      innerMargin,
      false
    );

    expect(resultRTL).toBeDefined();
    expect(resultRTL.constructor.name).toBe("FreeHighlightOutline");
  });

  it("should handle different box dimensions", () => {
    const testBox = [50, 50, 200, 200]; // Offset box

    const result = freeHighlightOutliner.newFreeDrawOutline(
      mockOutline,
      mockPoints,
      testBox,
      scaleFactor,
      innerMargin,
      isLTR
    );

    expect(result).toBeDefined();
    expect(result.constructor.name).toBe("FreeHighlightOutline");
  });

  it("should create different instances for different parameters", () => {
    const result1 = freeHighlightOutliner.newFreeDrawOutline(
      mockOutline,
      mockPoints,
      mockBox,
      scaleFactor,
      innerMargin,
      isLTR
    );

    const result2 = freeHighlightOutliner.newFreeDrawOutline(
      mockOutline,
      mockPoints,
      mockBox,
      2.0, // Different scaleFactor
      innerMargin,
      isLTR
    );

    expect(result1).not.toBe(result2);
    expect(result1.constructor.name).toBe("FreeHighlightOutline");
    expect(result2.constructor.name).toBe("FreeHighlightOutline");
  });

  it("should handle complex outlines with bezier curves", () => {
    // Create an outline with bezier curve segments
    const bezierOutline = new Float32Array(12);
    // Starting point
    bezierOutline[4] = 10;
    bezierOutline[5] = 10;
    // Bezier curve segment (not NaN at index 6)
    bezierOutline[6] = 20; // Control point 1 x
    bezierOutline[7] = 15; // Control point 1 y
    bezierOutline[8] = 40; // Control point 2 x
    bezierOutline[9] = 45; // Control point 2 y
    bezierOutline[10] = 50; // Endpoint x
    bezierOutline[11] = 50; // Endpoint y

    const result = freeHighlightOutliner.newFreeDrawOutline(
      bezierOutline,
      mockPoints,
      mockBox,
      scaleFactor,
      innerMargin,
      isLTR
    );

    expect(result).toBeDefined();
    expect(result.constructor.name).toBe("FreeHighlightOutline");
  });

  it("should handle multiple outline segments", () => {
    // Create a longer outline with 3 segments (18 elements)
    const longOutline = new Float32Array(18);

    // Segment 1: Starting point
    longOutline[4] = 10;
    longOutline[5] = 10;

    // Segment 1: Straight line
    longOutline[6] = NaN;
    longOutline[7] = 0;
    longOutline[8] = 0;
    longOutline[9] = 0;
    longOutline[10] = 30;
    longOutline[11] = 30;

    // Segment 2: Straight line
    longOutline[12] = NaN;
    longOutline[13] = 0;
    longOutline[14] = 0;
    longOutline[15] = 0;
    longOutline[16] = 50;
    longOutline[17] = 50;

    const longPoints = [10, 10, 30, 30, 50, 50];

    const result = freeHighlightOutliner.newFreeDrawOutline(
      longOutline,
      longPoints,
      mockBox,
      scaleFactor,
      innerMargin,
      isLTR
    );

    expect(result).toBeDefined();
    expect(result.constructor.name).toBe("FreeHighlightOutline");
  });

  it("should work with zero inner margin", () => {
    const result = freeHighlightOutliner.newFreeDrawOutline(
      mockOutline,
      mockPoints,
      mockBox,
      scaleFactor,
      0, // Zero inner margin
      isLTR
    );

    expect(result).toBeDefined();
    expect(result.constructor.name).toBe("FreeHighlightOutline");
  });

  it("should work with negative scale factor (edge case)", () => {
    const result = freeHighlightOutliner.newFreeDrawOutline(
      mockOutline,
      mockPoints,
      mockBox,
      -1.0, // Negative scale factor
      innerMargin,
      isLTR
    );

    expect(result).toBeDefined();
    expect(result.constructor.name).toBe("FreeHighlightOutline");
  });

  it("should preserve box property in created outline", () => {
    const result = freeHighlightOutliner.newFreeDrawOutline(
      mockOutline,
      mockPoints,
      mockBox,
      scaleFactor,
      innerMargin,
      isLTR
    );

    // FreeHighlightOutline should have a box property
    expect(result.box).toBeDefined();
    expect(Array.isArray(result.box) || result.box instanceof Float32Array).toBe(true);
  });

  it("should have firstPoint and lastPoint properties", () => {
    const result = freeHighlightOutliner.newFreeDrawOutline(
      mockOutline,
      mockPoints,
      mockBox,
      scaleFactor,
      innerMargin,
      isLTR
    );

    expect(result.firstPoint).toBeDefined();
    expect(result.lastPoint).toBeDefined();
    expect(Array.isArray(result.firstPoint)).toBe(true);
    expect(Array.isArray(result.lastPoint)).toBe(true);
    expect(result.firstPoint.length).toBe(2);
    expect(result.lastPoint.length).toBe(2);
  });

  it("should inherit from Outline class", () => {
    const result = freeHighlightOutliner.newFreeDrawOutline(
      mockOutline,
      mockPoints,
      mockBox,
      scaleFactor,
      innerMargin,
      isLTR
    );

    // FreeHighlightOutline extends Outline, so it should have Outline methods
    expect(typeof result.toSVGPath).toBe("function");
    expect(typeof result.serialize).toBe("function");
  });
});

