import { describe, expect, it, jest } from "@jest/globals";
import { FeatureTest } from "../../../src/shared/util.js";
import { convertBlackAndWhiteToRGBA } from "../../../src/shared/image_utils.js";

describe("convertBlackAndWhiteToRGBA", () => {
  beforeEach(() => {
    // Mock FeatureTest.isLittleEndian to control test environment
    jest.spyOn(FeatureTest, "isLittleEndian", "get").mockReturnValue(true);
  });

  afterEach(() => {
    jest.restoreAllMocks();
  });

  it("should convert 8x1 image with all white pixels", () => {
    const src = new Uint8Array([0xff]); // All 1s
    const dest = new Uint32Array(8);

    const result = convertBlackAndWhiteToRGBA({
      src,
      dest,
      width: 8,
      height: 1,
    });

    expect(result).toEqual({ srcPos: 1, destPos: 8 });

    // All pixels should be white (nonBlackColor default 0xffffffff)
    for (let i = 0; i < 8; i++) {
      expect(dest[i]).toBe(0xffffffff);
    }
  });

  it("should convert 8x1 image with all black pixels", () => {
    const src = new Uint8Array([0x00]); // All 0s
    const dest = new Uint32Array(8);

    const result = convertBlackAndWhiteToRGBA({
      src,
      dest,
      width: 8,
      height: 1,
    });

    expect(result).toEqual({ srcPos: 1, destPos: 8 });

    // All pixels should be black (0xff000000 for little endian)
    for (let i = 0; i < 8; i++) {
      expect(dest[i]).toBe(0xff000000);
    }
  });

  it("should convert 8x1 image with alternating pattern", () => {
    const src = new Uint8Array([0b10101010]); // 10101010
    const dest = new Uint32Array(8);

    const result = convertBlackAndWhiteToRGBA({
      src,
      dest,
      width: 8,
      height: 1,
    });

    expect(result).toEqual({ srcPos: 1, destPos: 8 });

    // Pattern: odd pixels (0,2,4,6) are 1 (white), even pixels (1,3,5,7) are 0 (black)
    for (let i = 0; i < 8; i++) {
      if (i % 2 === 0) {
        expect(dest[i]).toBe(0xffffffff); // white
      } else {
        expect(dest[i]).toBe(0xff000000); // black
      }
    }
  });

  it("should handle nonBlackColor parameter", () => {
    const src = new Uint8Array([0b11001100]); // 11001100
    const dest = new Uint32Array(8);
    const nonBlackColor = 0x00ff00ff; // magenta

    const result = convertBlackAndWhiteToRGBA({
      src,
      dest,
      width: 8,
      height: 1,
      nonBlackColor,
    });

    expect(result).toEqual({ srcPos: 1, destPos: 8 });

    // Pattern: 1 bits should be magenta, 0 bits should be black
    for (let i = 0; i < 8; i++) {
      if (i < 2 || (i >= 4 && i < 6)) {
        expect(dest[i]).toBe(0x00ff00ff); // magenta for 1 bits
      } else {
        expect(dest[i]).toBe(0xff000000); // black for 0 bits
      }
    }
  });

  it("should handle inverseDecode parameter", () => {
    const src = new Uint8Array([0b10101010]); // 10101010
    const dest = new Uint32Array(8);
    const nonBlackColor = 0x00ff00ff; // magenta

    const result = convertBlackAndWhiteToRGBA({
      src,
      dest,
      width: 8,
      height: 1,
      nonBlackColor,
      inverseDecode: true,
    });

    expect(result).toEqual({ srcPos: 1, destPos: 8 });

    // With inverseDecode: true, 0 maps to nonBlackColor and 1 maps to black
    for (let i = 0; i < 8; i++) {
      if (i % 2 === 0) {
        expect(dest[i]).toBe(0xff000000); // black for 1 bits
      } else {
        expect(dest[i]).toBe(0x00ff00ff); // magenta for 0 bits
      }
    }
  });

  it("should handle width not divisible by 8", () => {
    const src = new Uint8Array([0b11110000]); // 11110000, but only use first 5 bits
    const dest = new Uint32Array(5);

    const result = convertBlackAndWhiteToRGBA({
      src,
      dest,
      width: 5,
      height: 1,
    });

    expect(result).toEqual({ srcPos: 1, destPos: 5 });

    // First 5 bits: 1,1,1,1,0
    for (let i = 0; i < 5; i++) {
      if (i < 4) {
        expect(dest[i]).toBe(0xffffffff); // white for 1 bits
      } else {
        expect(dest[i]).toBe(0xff000000); // black for 0 bit
      }
    }
  });

  it("should handle multiple rows", () => {
    const src = new Uint8Array([0xff, 0x00, 0xaa]); // Row1: all 1s, Row2: all 0s, Row3: 10101010
    const dest = new Uint32Array(24); // 8 pixels x 3 rows

    const result = convertBlackAndWhiteToRGBA({
      src,
      dest,
      width: 8,
      height: 3,
    });

    expect(result).toEqual({ srcPos: 3, destPos: 24 });

    // Row 1: all white
    for (let i = 0; i < 8; i++) {
      expect(dest[i]).toBe(0xffffffff);
    }

    // Row 2: all black
    for (let i = 8; i < 16; i++) {
      expect(dest[i]).toBe(0xff000000);
    }

    // Row 3: alternating pattern starting with 1 (10101010)
    for (let i = 16; i < 24; i++) {
      const posInRow = i - 16;
      if (posInRow % 2 === 0) {
        expect(dest[i]).toBe(0xffffffff); // white for 1 bits
      } else {
        expect(dest[i]).toBe(0xff000000); // black for 0 bits
      }
    }
  });

  it("should handle srcPos parameter", () => {
    const src = new Uint8Array([0x00, 0xff, 0xaa]); // Skip first byte
    const dest = new Uint32Array(16); // 8 pixels x 2 rows

    const result = convertBlackAndWhiteToRGBA({
      src,
      srcPos: 1, // Start at second byte
      dest,
      width: 8,
      height: 2,
    });

    expect(result).toEqual({ srcPos: 3, destPos: 16 });

    // Row 1: byte at index 1 (0xff) = all white
    for (let i = 0; i < 8; i++) {
      expect(dest[i]).toBe(0xffffffff);
    }

    // Row 2: byte at index 2 (0xaa = 10101010) = alternating
    for (let i = 8; i < 16; i++) {
      const posInRow = i - 8;
      if (posInRow % 2 === 0) {
        expect(dest[i]).toBe(0xffffffff); // white for 1 bits
      } else {
        expect(dest[i]).toBe(0xff000000); // black for 0 bits
      }
    }
  });

  it("should handle big endian system", () => {
    // Mock big endian
    jest.spyOn(FeatureTest, "isLittleEndian", "get").mockReturnValue(false);

    const src = new Uint8Array([0b10101010]);
    const dest = new Uint32Array(8);

    const result = convertBlackAndWhiteToRGBA({
      src,
      dest,
      width: 8,
      height: 1,
    });

    expect(result).toEqual({ srcPos: 1, destPos: 8 });

    // In big endian, black is 0x000000ff (not 0xff000000)
    for (let i = 0; i < 8; i++) {
      if (i % 2 === 0) {
        expect(dest[i]).toBe(0xffffffff); // white
      } else {
        expect(dest[i]).toBe(0x000000ff); // black for big endian
      }
    }
  });

  it("should handle source shorter than needed (padding with 255)", () => {
    const src = new Uint8Array([0xff]); // Only 1 byte
    const dest = new Uint32Array(16); // But need 2 rows of 8 pixels

    const result = convertBlackAndWhiteToRGBA({
      src,
      dest,
      width: 8,
      height: 2,
    });

    expect(result).toEqual({ srcPos: 2, destPos: 16 });

    // Row 1: from actual src[0] = 0xff = all white
    for (let i = 0; i < 8; i++) {
      expect(dest[i]).toBe(0xffffffff);
    }

    // Row 2: from padding (255 = 0xff) = all white
    for (let i = 8; i < 16; i++) {
      expect(dest[i]).toBe(0xffffffff);
    }
  });

  it("should handle empty image (0 width or height)", () => {
    const src = new Uint8Array([0xff]);
    const dest = new Uint32Array(0);

    const result = convertBlackAndWhiteToRGBA({
      src,
      dest,
      width: 0,
      height: 0,
    });

    expect(result).toEqual({ srcPos: 0, destPos: 0 });
  });

  it("should handle dest as Uint8Array view", () => {
    const src = new Uint8Array([0xff, 0x00]);
    // Need buffer for 16 Uint32 elements = 16 * 4 = 64 bytes
    const buffer = new ArrayBuffer(64);
    const dest = new Uint8Array(buffer);

    const result = convertBlackAndWhiteToRGBA({
      src,
      dest,
      width: 8,
      height: 2,
    });

    expect(result).toEqual({ srcPos: 2, destPos: 16 });

    // Convert dest back to Uint32Array to check values
    const dest32 = new Uint32Array(buffer);

    // Row 1: all white
    for (let i = 0; i < 8; i++) {
      expect(dest32[i]).toBe(0xffffffff);
    }

    // Row 2: all black
    for (let i = 8; i < 16; i++) {
      expect(dest32[i]).toBe(0xff000000);
    }
  });

  it("should handle complex width with remainder", () => {
    // 13 pixels wide = 1 full byte + 5 remainder bits
    const src = new Uint8Array([0b11111111, 0b11111000]); // 13 ones, but we'll only use first 13 bits
    const dest = new Uint32Array(13);

    const result = convertBlackAndWhiteToRGBA({
      src,
      dest,
      width: 13,
      height: 1,
    });

    expect(result).toEqual({ srcPos: 2, destPos: 13 });

    // All 13 pixels should be white (1 bits)
    for (let i = 0; i < 13; i++) {
      expect(dest[i]).toBe(0xffffffff);
    }
  });

  it("should handle mixed patterns with width remainder", () => {
    // 10 pixels wide = 1 full byte + 2 remainder bits
    // Byte 1: 10101010, remainder bits: 11
    const src = new Uint8Array([0b10101010, 0b11000000]); // Note: remainder bits are highest bits
    const dest = new Uint32Array(10);

    const result = convertBlackAndWhiteToRGBA({
      src,
      dest,
      width: 10,
      height: 1,
    });

    expect(result).toEqual({ srcPos: 2, destPos: 10 });

    // First 8 pixels: 10101010 pattern
    for (let i = 0; i < 8; i++) {
      if (i % 2 === 0) {
        expect(dest[i]).toBe(0xffffffff); // 1 bits
      } else {
        expect(dest[i]).toBe(0xff000000); // 0 bits
      }
    }

    // Remaining 2 pixels: bits 8-9 = 11 (both 1s)
    expect(dest[8]).toBe(0xffffffff); // white
    expect(dest[9]).toBe(0xffffffff); // white
  });
});
